export type CollapsePlan = {
  before: number;
  afterStart: number;
};

export function getCollapsePlan(
  total: number,
  maxItems: number,
  itemsBeforeCollapse: number,
  itemsAfterCollapse: number | undefined,
): CollapsePlan | null {
  if (total <= maxItems) return null;

  const before = itemsBeforeCollapse;
  const after = itemsAfterCollapse ?? maxItems - before;

  if (after <= 0 || before + after >= total) return null;

  return {
    before,
    afterStart: total - after,
  };
}

import { useState, type HTMLAttributes, type ReactNode } from "react";
import { Button } from "./Button";
import { cn } from "@/lib/utils";

type StatusTheme = "gray" | "blue" | "green" | "amber" | "red";

export type AlertActionContext = {
  /** Emits the alert's dismiss event. The parent owns hiding the alert. */
  dismiss: () => void;
};

export type AlertAction = {
  label: string;
  onClick?: (context: AlertActionContext) => void | Promise<void>;
  theme?: "gray" | "blue" | "green" | "red";
  variant?: "solid" | "subtle" | "outline" | "ghost" | "link";
  size?: "xs" | "sm" | "md" | "lg";
  disabled?: boolean;
  loading?: boolean;
  icon?: ReactNode;
  iconLeft?: ReactNode;
  iconRight?: ReactNode;
};

export type AlertProps = Omit<HTMLAttributes<HTMLDivElement>, "title"> & {
  /** Main heading text. */
  title?: ReactNode;
  /** Supporting text; switches to the banner layout. */
  description?: ReactNode;
  /** Colors the status icon and row action label. */
  theme?: StatusTheme;
  /** Auto status icon by default; `false` hides it; a node replaces it. */
  icon?: boolean | ReactNode;
  primaryAction?: AlertAction;
  secondaryAction?: AlertAction;
  /** Shows the dismiss button and emits `dismiss`. */
  dismissible?: boolean;
  onDismiss?: () => void;
};

const iconColorClasses = {
  gray: "text-ink-gray-7",
  blue: "text-ink-blue-5",
  green: "text-ink-green-5",
  amber: "text-ink-amber-5",
  red: "text-ink-red-5",
};

const rowActionLabelClasses = {
  gray: "text-ink-gray-7",
  blue: "text-ink-blue-6",
  green: "text-ink-green-6",
  amber: "text-ink-amber-6",
  red: "text-ink-red-6",
};

function StatusIcon({ theme, className }: { theme: StatusTheme; className?: string }) {
  const shared = {
    viewBox: "0 0 16 16",
    fill: "none",
    "aria-hidden": true,
    className: cn("size-4", className),
  };

  if (theme === "green") {
    return (
      <svg {...shared}>
        <circle cx="8" cy="8" r="7" fill="currentColor" />
        <path
          d="M4.8 8.2l2.1 2.1 4.3-4.4"
          stroke="var(--surface-base)"
          strokeWidth="1.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    );
  }

  if (theme === "amber") {
    return (
      <svg {...shared}>
        <path d="M7.1 1.7L1.1 12a1.7 1.7 0 001.5 2.5h10.8a1.7 1.7 0 001.5-2.5L8.9 1.7a1.1 1.1 0 00-1.8 0z" fill="currentColor" />
        <path d="M8 5.2v3.6" stroke="var(--surface-base)" strokeWidth="1.5" strokeLinecap="round" />
        <circle cx="8" cy="11.4" r=".9" fill="var(--surface-base)" />
      </svg>
    );
  }

  if (theme === "red") {
    return (
      <svg {...shared}>
        <circle cx="8" cy="8" r="7" fill="currentColor" />
        <path
          d="M5.5 5.5l5 5m0-5l-5 5"
          stroke="var(--surface-base)"
          strokeWidth="1.5"
          strokeLinecap="round"
        />
      </svg>
    );
  }

  return (
    <svg {...shared}>
      <circle cx="8" cy="8" r="7" fill="currentColor" />
      <path d="M8 7.2v4" stroke="var(--surface-base)" strokeWidth="1.5" strokeLinecap="round" />
      <circle cx="8" cy="4.7" r=".9" fill="var(--surface-base)" />
    </svg>
  );
}

function XIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" aria-hidden="true" className="size-4">
      <path d="M4 4l8 8m0-8l-8 8" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}

export function Alert({
  title,
  description,
  theme = "gray",
  icon,
  primaryAction,
  secondaryAction,
  dismissible = false,
  onDismiss,
  className,
  ...props
}: AlertProps) {
  const [pending, setPending] = useState({ primary: false, secondary: false });
  const layout = description || secondaryAction ? "banner" : "row";
  const role = theme === "red" || theme === "amber" ? "alert" : "status";
  const showPrefix = icon !== false;

  function dismiss() {
    onDismiss?.();
  }

  async function runAction(slot: "primary" | "secondary", action: AlertAction | undefined) {
    if (!action?.onClick || pending[slot]) return;
    setPending((current) => ({ ...current, [slot]: true }));
    try {
      await action.onClick({ dismiss });
    } finally {
      setPending((current) => ({ ...current, [slot]: false }));
    }
  }

  function renderIcon() {
    if (icon === false) return null;
    if (icon === true || icon === undefined) {
      return <StatusIcon theme={theme} className={iconColorClasses[theme]} />;
    }
    if (typeof icon === "string" && icon.startsWith("lucide-")) {
      return <span className={cn("size-4", icon, iconColorClasses[theme])} aria-hidden="true" />;
    }
    return (
      <span className={cn("flex size-4 items-center justify-center", iconColorClasses[theme])}>
        {icon}
      </span>
    );
  }

  function actionButton(slot: "primary" | "secondary", action: AlertAction | undefined) {
    if (!action) return null;
    const { label, onClick, ...buttonProps } = action;
    const isLoading = action.loading ?? pending[slot];
    const isRow = layout === "row";

    return (
      <Button
        {...buttonProps}
        label={label}
        theme={action.theme ?? "gray"}
        variant={action.variant ?? (isRow ? "ghost" : slot === "primary" ? "outline" : "ghost")}
        size={action.size ?? (isRow ? "sm" : "md")}
        loading={isLoading}
        onClick={() => runAction(slot, action)}
        className={cn(
          isRow && !action.variant && !action.theme && rowActionLabelClasses[theme],
          !isRow && slot === "primary" && !action.variant && "border-transparent! shadow-sm",
          !isRow && slot === "secondary" && !action.variant && !action.theme && "text-ink-gray-7",
        )}
      />
    );
  }

  const dismissButton = dismissible ? (
    <Button
      data-slot="dismiss"
      variant="ghost"
      theme="gray"
      size={layout === "row" ? "sm" : "xs"}
      aria-label="Dismiss"
      onClick={dismiss}
      className={layout === "row" ? "shrink-0" : "absolute right-1.5 top-1.5"}
    >
      <XIcon />
    </Button>
  ) : null;

  if (layout === "row") {
    return (
      <div
        role={role}
        data-layout="row"
        data-color={theme}
        className={cn(
          "flex h-10 items-center rounded-(--alert-radius) bg-surface-gray-1 py-1.5 pl-3.5 pr-1.5",
          className,
        )}
        {...props}
      >
        {showPrefix ? (
          <div data-slot="prefix" className="mr-2 flex size-4 shrink-0 items-center justify-center">
            {renderIcon()}
          </div>
        ) : null}
        <div data-slot="title" className="min-w-0 flex-1 truncate text-sm font-medium text-ink-gray-8">
          {title}
        </div>
        {primaryAction ? (
          <div data-slot="actions" className="ml-1.5 flex shrink-0 items-center gap-1">
            {actionButton("primary", primaryAction)}
          </div>
        ) : null}
        {dismissible ? <div className="ml-1 flex shrink-0">{dismissButton}</div> : null}
      </div>
    );
  }

  const showActions = Boolean(primaryAction || secondaryAction);

  return (
    <div
      role={role}
      data-layout="banner"
      data-color={theme}
      className={cn("relative rounded-(--alert-radius) bg-surface-gray-1 p-3", className)}
      {...props}
    >
      <div className={cn("flex items-center gap-1.5", dismissible && "pr-8")}>
        {showPrefix ? (
          <div data-slot="prefix" className="flex size-4 shrink-0 items-center justify-center">
            {renderIcon()}
          </div>
        ) : null}
        {title ? (
          <div data-slot="title" className="min-w-0 text-sm font-medium text-ink-gray-8">
            {title}
          </div>
        ) : null}
      </div>
      {description || showActions ? (
        <div className="mt-1 flex flex-col items-start gap-3">
          {description ? (
            <p data-slot="description" className="text-sm text-ink-gray-6">
              {description}
            </p>
          ) : null}
          {showActions ? (
            <div data-slot="actions" className="flex items-center gap-1">
              {actionButton("primary", primaryAction)}
              {actionButton("secondary", secondaryAction)}
            </div>
          ) : null}
        </div>
      ) : null}
      {dismissButton}
    </div>
  );
}

/* Alert component tokens. */
:root {
  --alert-radius: var(--radius-6);
}

import { forwardRef, useEffect, useState } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { User } from "lucide-react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

const avatarFaceVariants = cva(
  "inline-flex shrink-0 items-center justify-center overflow-hidden font-medium",
  {
    variants: {
      size: {
        xs: "size-(--avatar-xs-size) [font-size:var(--avatar-xs-font-size)]",
        sm: "size-(--avatar-sm-size) [font-size:var(--avatar-sm-font-size)]",
        md: "size-(--avatar-md-size) [font-size:var(--avatar-md-font-size)]",
        lg: "size-(--avatar-lg-size) [font-size:var(--avatar-lg-font-size)]",
        xl: "size-(--avatar-xl-size) [font-size:var(--avatar-xl-font-size)]",
        "2xl": "size-(--avatar-2xl-size) [font-size:var(--avatar-2xl-font-size)]",
        "3xl": "size-(--avatar-3xl-size) [font-size:var(--avatar-3xl-font-size)]",
      },
      shape: {
        squircle: "",
        circle: "rounded-full",
      },
    },
    compoundVariants: [
      { shape: "squircle", size: "xs", class: "rounded-(--avatar-xs-radius)" },
      { shape: "squircle", size: "sm", class: "rounded-(--avatar-sm-radius)" },
      { shape: "squircle", size: "md", class: "rounded-(--avatar-md-radius)" },
      { shape: "squircle", size: "lg", class: "rounded-(--avatar-lg-radius)" },
      { shape: "squircle", size: "xl", class: "rounded-(--avatar-xl-radius)" },
      { shape: "squircle", size: "2xl", class: "rounded-(--avatar-2xl-radius)" },
      { shape: "squircle", size: "3xl", class: "rounded-(--avatar-3xl-radius)" },
    ],
    defaultVariants: {
      size: "md",
      shape: "circle",
    },
  },
);

const avatarThemeClasses = {
  gray: "bg-surface-gray-2 text-ink-gray-5",
  blue: "bg-surface-blue-2 text-ink-blue-7",
  green: "bg-surface-green-2 text-ink-green-7",
  amber: "bg-surface-amber-2 text-ink-amber-7",
  red: "bg-surface-red-2 text-ink-red-7",
  violet: "bg-surface-violet-2 text-ink-violet-7",
} as const;

const fallbackIconSizeClasses = {
  xs: "[width:var(--avatar-xs-icon-size)] [height:var(--avatar-xs-icon-size)]",
  sm: "[width:var(--avatar-sm-icon-size)] [height:var(--avatar-sm-icon-size)]",
  md: "[width:var(--avatar-md-icon-size)] [height:var(--avatar-md-icon-size)]",
  lg: "[width:var(--avatar-lg-icon-size)] [height:var(--avatar-lg-icon-size)]",
  xl: "[width:var(--avatar-xl-icon-size)] [height:var(--avatar-xl-icon-size)]",
  "2xl": "[width:var(--avatar-2xl-icon-size)] [height:var(--avatar-2xl-icon-size)]",
  "3xl": "[width:var(--avatar-3xl-icon-size)] [height:var(--avatar-3xl-icon-size)]",
} as const;

const indicatorShellClasses = {
  xs: "-mr-[.1rem] -mb-[.1rem] size-2",
  sm: "-mr-[.1rem] -mb-[.1rem] size-[9px]",
  md: "-mr-[.1rem] -mb-[.1rem] size-2.5",
  lg: "-mr-[.1rem] -mb-[.1rem] size-3",
  xl: "-mr-[.1rem] -mb-[.1rem] size-3",
  "2xl": "-mr-[.1rem] -mb-[.1rem] size-3.5",
  "3xl": "-mr-[.2rem] -mb-[.2rem] size-4",
} as const;

type AvatarSize = NonNullable<VariantProps<typeof avatarFaceVariants>["size"]>;
type AvatarShape = NonNullable<VariantProps<typeof avatarFaceVariants>["shape"]> | "square";
type AvatarTheme = keyof typeof avatarThemeClasses;

export type AvatarProps = Omit<ComponentPropsWithoutRef<"span">, "children"> & {
  /** Image URL used for the avatar. */
  image?: string;
  /** Full name used for the fallback initial and the accessible label. */
  label?: string;
  /** Visual colour theme used for the fallback. */
  theme?: AvatarTheme;
  /** @deprecated Use `image`. */
  src?: string;
  /** @deprecated Use `label`. */
  alt?: string;
  /** @deprecated Use `label`. */
  fallback?: string;
  size?: AvatarSize;
  shape?: AvatarShape;
  /** Optional content shown at the bottom-right of the avatar. */
  indicator?: ReactNode;
  /** @deprecated Use `indicator`. */
  status?: ReactNode;
  /** Optional classes applied to the indicator shell. */
  statusClassName?: string;
  /** Custom fallback content shown instead of the initial. */
  children?: ReactNode;
};

export const Avatar = forwardRef<HTMLSpanElement, AvatarProps>(
  (
    {
      className,
      image,
      label,
      theme = "gray",
      src = "",
      alt = "",
      fallback = "",
      size = "md",
      shape = "circle",
      indicator,
      status,
      statusClassName,
      children,
      ...props
    },
    ref,
  ) => {
    const [imageError, setImageError] = useState(false);
    const imageSrc = image ?? src;
    const displayLabel = label ?? fallback ?? alt;
    const accessibleLabel = displayLabel || "User avatar";
    const initial = displayLabel.trim().slice(0, 1).toUpperCase();
    const showImage = Boolean(imageSrc) && !imageError;
    const shapeVariant = shape === "square" ? "squircle" : shape;
    const indicatorContent = indicator ?? status;

    useEffect(() => {
      setImageError(false);
    }, [imageSrc]);

    return (
      <span
        ref={ref}
        role="img"
        aria-label={accessibleLabel}
        data-size={size}
        data-shape={shape}
        data-theme={theme}
        className={cn("relative inline-flex shrink-0 select-none", className)}
        {...props}
      >
        <span className={cn(avatarFaceVariants({ size, shape: shapeVariant }), !showImage && avatarThemeClasses[theme])}>
          {showImage ? (
            <img
              src={imageSrc}
              alt=""
              className="size-full object-cover"
              onError={() => {
                setImageError(true);
              }}
            />
          ) : children ? (
            <span className={cn("inline-flex items-center justify-center", fallbackIconSizeClasses[size])}>
              {children}
            </span>
          ) : initial ? (
            <span aria-hidden="true">{initial}</span>
          ) : (
            <User className={cn(fallbackIconSizeClasses[size], "text-current")} aria-hidden="true" />
          )}
        </span>
        {indicatorContent ? (
          <span
            aria-hidden="true"
            className={cn(
              "absolute bottom-0 right-0 grid place-items-center rounded-full bg-(--avatar-status-bg) [box-shadow:0_0_0_var(--avatar-status-ring-width)_var(--avatar-status-ring)]",
              indicatorShellClasses[size],
              statusClassName,
            )}
          >
            <span className="grid size-full place-items-center">{indicatorContent}</span>
          </span>
        ) : null}
      </span>
    );
  },
);

Avatar.displayName = "Avatar";

/* Avatar component tokens — override these to customise avatars. */
:root {
  /* Per-size dimensions */
  --avatar-xs-size: 16px;
  --avatar-sm-size: 20px;
  --avatar-md-size: 24px;
  --avatar-lg-size: 28px;
  --avatar-xl-size: 32px;
  --avatar-2xl-size: 40px;
  --avatar-3xl-size: 46px;

  /* Per-size square radii (frappe-ui v1) */
  --avatar-xs-radius: 4px;
  --avatar-sm-radius: 5px;
  --avatar-md-radius: 5px;
  --avatar-lg-radius: 6px;
  --avatar-xl-radius: 6px;
  --avatar-2xl-radius: 8px;
  --avatar-3xl-radius: 10px;

  /* Per-size initials font sizes */
  --avatar-xs-font-size: 11px;
  --avatar-sm-font-size: 13px;
  --avatar-md-font-size: 14px;
  --avatar-lg-font-size: 14px;
  --avatar-xl-font-size: 16px;
  --avatar-2xl-font-size: 18px;
  --avatar-3xl-font-size: 20px;

  /* Per-size fallback icon sizes */
  --avatar-xs-icon-size: 10px;
  --avatar-sm-icon-size: 12px;
  --avatar-md-icon-size: 14px;
  --avatar-lg-icon-size: 16px;
  --avatar-xl-icon-size: 18px;
  --avatar-2xl-icon-size: 22px;
  --avatar-3xl-icon-size: 24px;

  /* Surfaces */
  --avatar-bg: var(--surface-gray-2);
  --avatar-fg: var(--ink-gray-5);

  /* Indicator shell — slot content fills the shell */
  --avatar-status-icon-size: 6px;
  --avatar-status-bg: var(--surface-base);
  --avatar-status-ring: var(--surface-base);
  --avatar-status-ring-width: 2px;
}

import { Avatar } from "./Avatar";
import { cn } from "@/lib/utils";

const overlapClasses = {
  xs: "-ml-(--avatar-group-overlap-xs)",
  sm: "-ml-(--avatar-group-overlap-sm)",
  md: "-ml-(--avatar-group-overlap-md)",
  lg: "-ml-(--avatar-group-overlap-lg)",
  xl: "-ml-(--avatar-group-overlap-xl)",
  "2xl": "-ml-(--avatar-group-overlap-2xl)",
  "3xl": "-ml-(--avatar-group-overlap-3xl)",
} as const;

const labelSizeClasses = {
  xs: "[font-size:var(--avatar-group-label-xs-font-size)]",
  sm: "[font-size:var(--avatar-group-label-sm-font-size)]",
  md: "[font-size:var(--avatar-group-label-md-font-size)]",
  lg: "[font-size:var(--avatar-group-label-lg-font-size)]",
  xl: "[font-size:var(--avatar-group-label-xl-font-size)]",
  "2xl": "[font-size:var(--avatar-group-label-2xl-font-size)]",
  "3xl": "[font-size:var(--avatar-group-label-3xl-font-size)]",
} as const;

const countFaceClasses = {
  xs: "size-(--avatar-xs-size) [font-size:var(--avatar-xs-font-size)]",
  sm: "size-(--avatar-sm-size) [font-size:var(--avatar-sm-font-size)]",
  md: "size-(--avatar-md-size) [font-size:var(--avatar-md-font-size)]",
  lg: "size-(--avatar-lg-size) [font-size:var(--avatar-lg-font-size)]",
  xl: "size-(--avatar-xl-size) [font-size:var(--avatar-xl-font-size)]",
  "2xl": "size-(--avatar-2xl-size) [font-size:var(--avatar-2xl-font-size)]",
  "3xl": "size-(--avatar-3xl-size) [font-size:var(--avatar-3xl-font-size)]",
} as const;

const ringClass =
  "[&>span:first-child]:[box-shadow:0_0_0_var(--avatar-group-ring-width)_var(--avatar-group-ring)]";

type AvatarGroupSize = keyof typeof overlapClasses;

export type AvatarGroupItem = {
  image?: string;
  label?: string;
  theme?: "gray" | "blue" | "green" | "amber" | "red" | "violet";
  src?: string;
  alt?: string;
  fallback?: string;
};

export type AvatarGroupProps = {
  items?: AvatarGroupItem[];
  max?: number;
  showCount?: boolean;
  count?: number;
  size?: AvatarGroupSize;
  className?: string;
};

export function AvatarGroup({
  items = [],
  max = 5,
  showCount = false,
  count = 0,
  size = "md",
  className,
}: AvatarGroupProps) {
  const visibleItems = items.slice(0, max);
  const overflowCount = items.length > max ? items.length - max : 0;
  const memberCount = count > 0 ? count : items.length;

  return (
    <div role="group" className={cn("inline-flex items-center gap-3", className)} data-size={size}>
      <div className="inline-flex items-center">
        {visibleItems.map((item, index) => (
          <Avatar
            key={`${item.image ?? item.src ?? item.label ?? item.fallback ?? "avatar"}-${index}`}
            image={item.image ?? item.src}
            label={item.label ?? item.fallback ?? item.alt}
            theme={item.theme}
            size={size}
            shape="circle"
            className={cn(ringClass, index > 0 && overlapClasses[size])}
            style={{ zIndex: visibleItems.length - index }}
          />
        ))}
        {overflowCount > 0 ? (
          <span
            role="img"
            aria-label={`+${overflowCount}`}
            className={cn(
              "inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-(--avatar-bg) font-medium text-(--avatar-fg) [box-shadow:0_0_0_var(--avatar-group-ring-width)_var(--avatar-group-ring)]",
              countFaceClasses[size],
              visibleItems.length > 0 && overlapClasses[size],
            )}
            style={{ zIndex: 0 }}
          >
            {`+${overflowCount}`}
          </span>
        ) : null}
      </div>
      {showCount ? (
        <span className={cn("text-(--avatar-group-label-fg)", labelSizeClasses[size])}>
          {memberCount} {memberCount === 1 ? "member" : "members"}
        </span>
      ) : null}
    </div>
  );
}

/* Avatar group component tokens — override these to customise avatar stacks. */
:root {
  --avatar-group-ring: var(--surface-base);
  --avatar-group-ring-width: 2px;

  --avatar-group-overlap-xs: 2px;
  --avatar-group-overlap-sm: 4px;
  --avatar-group-overlap-md: 4px;
  --avatar-group-overlap-lg: 5px;
  --avatar-group-overlap-xl: 4px;
  --avatar-group-overlap-2xl: 6px;
  --avatar-group-overlap-3xl: 8px;

  --avatar-group-label-fg: var(--ink-gray-5);

  --avatar-group-label-xs-font-size: 11px;
  --avatar-group-label-sm-font-size: 11px;
  --avatar-group-label-md-font-size: 14px;
  --avatar-group-label-lg-font-size: 14px;
  --avatar-group-label-xl-font-size: 16px;
  --avatar-group-label-2xl-font-size: 18px;
  --avatar-group-label-3xl-font-size: 20px;
}

import { ark } from "@ark-ui/react/factory";
import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex shrink-0 select-none items-center gap-(--badge-gap) overflow-clip whitespace-nowrap rounded-(--badge-radius) leading-tighter [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      theme: {
        gray: "",
        blue: "",
        green: "",
        amber: "",
        red: "",
        violet: "",
      },
      variant: {
        solid: "",
        subtle: "",
