  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";
import { getCollapsePlan } from "@/lib/collapse";

const breadcrumbInteractiveVariants = cva(
  "relative inline-flex cursor-pointer items-center gap-2 rounded-(--breadcrumb-item-radius) font-medium antialiased outline-none transition-[color,transform] duration-(--breadcrumb-transition-duration) ease-out focus-visible:[outline:var(--focus-outline-default)] active:scale-[0.98] before:pointer-events-none before:absolute before:content-[''] before:[inset:var(--breadcrumb-hit-inset)] [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
