import { forwardRef, useEffect, useId, useImperativeHandle, useRef, useState } from "react";
import { Check, Minus } from "lucide-react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

const sizeClasses = {
  xs: "size-(--checkbox-xs-size)",
  sm: "size-(--checkbox-sm-size)",
  md: "size-(--checkbox-md-size)",
};

const iconSizeClasses = {
  xs: "size-2",
  sm: "size-2.5",
  md: "size-3",
};

const paddedSizeClasses = {
  xs: "h-(--checkbox-xs-height) px-1.5",
  sm: "h-(--checkbox-sm-height) px-1.5",
  md: "h-(--checkbox-md-height) px-3",
};

const requiredMark = (
  <>
    <span className="select-none [color:var(--label-required-color,var(--ink-red-5))]" aria-hidden="true">
      *
    </span>
    <span className="sr-only">(required)</span>
  </>
);

type CheckboxSize = keyof typeof sizeClasses;

export type CheckboxProps = Omit<ComponentPropsWithoutRef<"input">, "size" | "type"> & {
  /** Controls the size of the checkbox. */
  size?: CheckboxSize;
  /** Wraps the control and label in a clickable surface. */
  padded?: boolean;
  /** Renders the mixed state. Set through the prop, not markup. */
  indeterminate?: boolean;
  /** Label rendered beside the checkbox. */
  label?: ReactNode;
  /** Helper text rendered below the checkbox. Hidden when `error` is set. */
  description?: ReactNode;
  /** Error message; marks the checkbox invalid. */
  error?: ReactNode;
  /** Marks the field as required and renders an asterisk. */
  required?: boolean;
};

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      className,
      id,
      size = "sm",
      padded = false,
      indeterminate = false,
      label,
      description,
      error,
      required,
      disabled,
      checked,
      defaultChecked,
      onChange,
      "aria-describedby": ariaDescribedBy,
      ...props
    },
    ref,
  ) => {
    const generatedId = useId();
    const inputId = id ?? generatedId;
    const descriptionId = `${inputId}-description`;
    const errorId = `${inputId}-error`;
    const hasError = Boolean(error);
    const hasLabel = Boolean(label);
    const hasDetail = Boolean(description || error);
    const isControlled = checked !== undefined;
    const [internalChecked, setInternalChecked] = useState(Boolean(defaultChecked));
    const isChecked = isControlled ? Boolean(checked) : internalChecked;
    const [mixed, setMixed] = useState(indeterminate);
    const inputRef = useRef<HTMLInputElement | null>(null);

    useImperativeHandle(ref, () => inputRef.current as HTMLInputElement);

    useEffect(() => {
      setMixed(indeterminate);
    }, [indeterminate]);

    useEffect(() => {
      if (inputRef.current) inputRef.current.indeterminate = mixed;
    }, [mixed]);

    const describedBy =
      [
        description && !hasError ? descriptionId : null,
        hasError ? errorId : null,
        ariaDescribedBy,
      ]
        .filter(Boolean)
        .join(" ") || undefined;

    return (
      <div
        className={cn(
          "flex-col",
          padded ? "flex" : "inline-flex",
          padded && "group rounded-(--checkbox-padded-radius) transition-colors",
          padded &&
            !disabled &&
            "cursor-pointer hover:bg-surface-gray-3 active:bg-surface-gray-4 [&:has(:focus-visible)]:ring-2 [&:has(:focus-visible)]:ring-ink-gray-8 [&:has(:focus-visible)]:ring-offset-2 [&:has(:focus-visible)]:ring-offset-surface-base [&_input:focus-visible]:ring-0 [&_input:focus-visible]:ring-offset-0",
          padded && disabled && "cursor-not-allowed",
          padded &&
            (hasDetail
              ? size === "md"
                ? "px-3 py-2"
                : "px-1.5 py-1.5"
              : paddedSizeClasses[size]),
          className,
        )}
        onClick={(event) => {
          if (disabled) return;
          const target = event.target as HTMLElement;
          if (target.closest('input[type="checkbox"]') || target.closest("label")) return;
          inputRef.current?.click();
        }}
      >
        <div className="inline-flex items-center gap-(--checkbox-label-gap)">
          <span className="relative inline-flex shrink-0 items-center justify-center">
            <input
              ref={inputRef}
              id={inputId}
              type="checkbox"
              checked={isControlled ? Boolean(checked) : undefined}
              defaultChecked={isControlled ? undefined : defaultChecked}
              disabled={disabled}
              required={required}
              aria-required={required || undefined}
              aria-invalid={hasError || undefined}
              aria-errormessage={hasError ? errorId : undefined}
              aria-describedby={describedBy}
              aria-checked={mixed ? "mixed" : undefined}
              data-slot="control"
              data-size={size}
              data-state={mixed ? "indeterminate" : isChecked ? "checked" : "unchecked"}
              data-disabled={disabled ? "true" : undefined}
              data-required={required ? "true" : undefined}
              className={cn(
                "peer shrink-0 appearance-none rounded-(--checkbox-radius) border bg-surface-base text-surface-base transition-colors outline-none",
                sizeClasses[size],
                "checked:border-surface-gray-10 checked:bg-surface-gray-10 indeterminate:border-surface-gray-10 indeterminate:bg-surface-gray-10 aria-invalid:border-outline-red-6",
                disabled
                  ? "cursor-not-allowed border-outline-gray-3 text-surface-gray-5 opacity-60"
                  : "cursor-pointer border-outline-gray-4 hover:border-outline-gray-5 focus-visible:ring-2 focus-visible:ring-ink-gray-8 focus-visible:ring-offset-2 focus-visible:ring-offset-surface-base",
              )}
              onChange={(event) => {
                if (!isControlled) setInternalChecked(event.currentTarget.checked);
                setMixed(false);
                if (inputRef.current) inputRef.current.indeterminate = false;
                onChange?.(event);
              }}
              {...props}
            />
            {mixed ? (
              <Minus
                aria-hidden="true"
                className={cn("pointer-events-none absolute text-surface-base", iconSizeClasses[size])}
                strokeWidth={3}
              />
            ) : (
              <Check
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute text-surface-base opacity-0 peer-checked:opacity-100",
                  iconSizeClasses[size],
                )}
                strokeWidth={3}
              />
            )}
          </span>
          {hasLabel ? (
            <label
              htmlFor={inputId}
              className={cn(
                "select-none [font-size:var(--label-font-size,13px)] [font-weight:var(--label-font-weight,420)] leading-tighter [color:var(--label-color,var(--ink-gray-6))]",
                disabled
                  ? "cursor-not-allowed [color:var(--label-disabled-color,var(--ink-gray-4))]"
                  : "cursor-pointer",
              )}
            >
              {label}
              {required ? requiredMark : null}
            </label>
          ) : null}
        </div>
        {hasDetail ? (
          <div className={cn("ps-[1.35rem] mt-1", !hasLabel && "ps-0")}>
            {description && !hasError ? (
              <p
                id={descriptionId}
                className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-gray-5"
              >
                {description}
              </p>
            ) : null}
            {hasError ? (
              <p
                id={errorId}
                role="alert"
                className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-red-7"
              >
                {error}
              </p>
            ) : null}
          </div>
        ) : null}
      </div>
    );
  },
);

Checkbox.displayName = "Checkbox";

/* Checkbox component tokens — mirrors frappe-ui v1 toggle geometry. */
:root {
  --checkbox-xs-size: 13px;
  --checkbox-sm-size: 14px;
  --checkbox-md-size: 16px;
  --checkbox-radius: var(--radius-1);
  --checkbox-padded-radius: var(--radius-4);
  --checkbox-label-gap: 8px;

  --checkbox-xs-height: 24px;
  --checkbox-sm-height: 28px;
  --checkbox-md-height: 32px;

  --input-description-font-size: 13px;
}

import { useState } from "react";
import type { ReactNode } from "react";
import { Dialog as ArkDialog } from "@ark-ui/react/dialog";
import { Portal } from "@ark-ui/react/portal";
import { X } from "lucide-react";
import { Button } from "./Button";
import { cn } from "@/lib/utils";

export type DialogSize =
  | "xs"
  | "sm"
  | "md"
  | "lg"
  | "xl"
  | "2xl"
  | "3xl"
  | "4xl"
  | "5xl"
  | "6xl"
  | "7xl";
export type DialogTheme = "gray" | "blue" | "green" | "amber" | "red";
export type DialogPosition = "center" | "top";

export type DialogAction = {
  /** Button label. */
  label: string;
  /** Button theme. */
  theme?: "gray" | "blue" | "green" | "red";
  /** Button variant. */
  variant?: "solid" | "subtle" | "outline" | "ghost" | "link";
  /** Button size. */
  size?: "xs" | "sm" | "md" | "lg";
  /** Disables the button. */
  disabled?: boolean;
  /** Runs when the button is pressed. A promise shows a spinner until it settles. */
  onClick?: () => void | Promise<void>;
};

export type DialogProps = {
  /** Whether the dialog is open. Omit for uncontrolled use. */
  open?: boolean;
  /** Initially open, for uncontrolled use. */
  defaultOpen?: boolean;
  /** Called when the open state changes. */
  onOpenChange?: (open: boolean) => void;
  /** Title shown in the header. */
  title?: ReactNode;
  /** Short paragraph under the title. */
  message?: ReactNode;
  /** Icon shown in a badge next to the title. */
  icon?: ReactNode;
  /** Tone of the icon badge. */
  theme?: DialogTheme;
  /** Maximum width of the dialog. */
  size?: DialogSize;
  /** Vertical placement. */
  position?: DialogPosition;
  /** Allow Escape and an outside click to close the dialog. */
  dismissible?: boolean;
  /** Show the close button in the header. */
  showCloseButton?: boolean;
  /** Drop the header, the padded card and the action row. */
  bare?: boolean;
  /** Buttons shown in the footer. */
  actions?: DialogAction[];
  /** Element that opens the dialog. */
  trigger?: ReactNode;
  /** Body content. */
  children?: ReactNode;
  /** Class applied to the dialog card. */
  className?: string;
};

const sizeClasses = {
  xs: "max-w-xs",
  sm: "max-w-sm",
  md: "max-w-md",
  lg: "max-w-lg",
  xl: "max-w-xl",
  "2xl": "max-w-2xl",
  "3xl": "max-w-3xl",
  "4xl": "max-w-4xl",
  "5xl": "max-w-5xl",
  "6xl": "max-w-6xl",
  "7xl": "max-w-7xl",
};

const iconBadgeClasses = {
  gray: "bg-surface-gray-2 text-ink-gray-7",
  blue: "bg-surface-blue-2 text-ink-blue-7",
  green: "bg-surface-green-2 text-ink-green-7",
  amber: "bg-surface-amber-2 text-ink-amber-7",
  red: "bg-surface-red-2 text-ink-red-7",
};

export function Dialog({
  open,
  defaultOpen = false,
  onOpenChange,
  title,
  message,
  icon,
  theme = "gray",
  size = "lg",
  position = "center",
  dismissible = true,
  showCloseButton = true,
  bare = false,
  actions = [],
  trigger,
  children,
  className,
}: DialogProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const [loadingIndex, setLoadingIndex] = useState<number | null>(null);
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  function setOpen(next: boolean) {
    if (!isControlled) setInternalOpen(next);
    onOpenChange?.(next);
  }

  async function runAction(action: DialogAction, index: number) {
    if (!action.onClick) return;
    const result = action.onClick();
    if (!result || typeof (result as Promise<void>).then !== "function") return;
    setLoadingIndex(index);
    try {
      await result;
    } finally {
      setLoadingIndex(null);
    }
  }

  return (
    <ArkDialog.Root
      open={isOpen}
      onOpenChange={(details) => setOpen(details.open)}
      closeOnEscape={dismissible}
      closeOnInteractOutside={dismissible}
      lazyMount
      unmountOnExit
    >
      {trigger ? <ArkDialog.Trigger asChild>{trigger}</ArkDialog.Trigger> : null}
      <Portal>
        <ArkDialog.Backdrop
          data-slot="dialog-overlay"
          className="fixed inset-0 z-50 [--z-index:50]! bg-black-overlay-200 outline-none"
        />
        <ArkDialog.Positioner
          data-slot="dialog-positioner"
          className={cn(
            "fixed inset-0 z-50 [--z-index:50]! flex justify-center overflow-y-auto p-4",
            position === "top" ? "items-start pt-16" : "items-center",
          )}
        >
          <ArkDialog.Content
            data-slot="dialog-content"
            className={cn(
              "w-full rounded-7 bg-surface-elevation-1 text-start shadow-xl outline-none",
              sizeClasses[size],
              className,
            )}
          >
            {bare ? (
              children
            ) : (
              <>
                <div className="px-4 pb-6 pt-5 sm:px-6">
                  <div className="flex items-center justify-between gap-2">
                    <div className="flex flex-1 items-center gap-2">
                      {icon ? (
                        <span
                          data-slot="dialog-icon"
                          className={cn(
                            "flex size-7 shrink-0 items-center justify-center rounded-full",
                            iconBadgeClasses[theme],
                          )}
                        >
                          {icon}
                        </span>
                      ) : null}
                      <ArkDialog.Title asChild>
                        <h3 className="flex-1 text-lg font-semibold leading-6 text-ink-gray-8">
                          {title}
                        </h3>
                      </ArkDialog.Title>
                    </div>
                    {showCloseButton ? (
                      <ArkDialog.CloseTrigger asChild>
                        <Button
                          variant="ghost"
                          theme="gray"
                          aria-label="Close"
                          icon={<X aria-hidden="true" className="size-4 text-ink-gray-9" />}
                        />
                      </ArkDialog.CloseTrigger>
                    ) : null}
                  </div>
                  {message ? (
                    <ArkDialog.Description asChild>
                      <p className="mt-2 text-sm text-ink-gray-7">{message}</p>
                    </ArkDialog.Description>
                  ) : null}
                  {children}
                </div>
                {actions.length ? (
                  <div
                    data-slot="dialog-actions"
                    className="flex justify-end gap-2 px-4 pb-7 pt-4 sm:px-6"
                  >
                    {actions.map((action, index) => (
                      <Button
                        key={action.label}
                        theme={action.theme ?? "gray"}
                        variant={action.variant ?? "subtle"}
                        size={action.size ?? "sm"}
                        label={action.label}
                        disabled={action.disabled}
                        loading={loadingIndex === index}
                        onClick={() => runAction(action, index)}
                      />
                    ))}
                  </div>
                ) : null}
              </>
            )}
          </ArkDialog.Content>
        </ArkDialog.Positioner>
      </Portal>
    </ArkDialog.Root>
  );
}

/* The dialog enters on a short scale-and-lift, and the scrim fades. */
@keyframes espresso-dialog-overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes espresso-dialog-content-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* The scrim is heavier in the dark theme, so the card still reads as the
   surface in front. */
[data-theme="dark"] [data-slot="dialog-overlay"] {
  background-color: var(--color-black-overlay-700);
}

[data-slot="dialog-overlay"][data-state="open"] {
  animation: espresso-dialog-overlay-in 150ms ease-out;
}

[data-slot="dialog-overlay"][data-state="closed"] {
  animation: espresso-dialog-overlay-in 150ms ease-out reverse;
}

[data-slot="dialog-content"][data-state="open"] {
  animation: espresso-dialog-content-in 180ms cubic-bezier(0.23, 1, 0.32, 1);
}

[data-slot="dialog-content"][data-state="closed"] {
  animation: espresso-dialog-content-in 180ms cubic-bezier(0.23, 1, 0.32, 1) reverse;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="dialog-overlay"],
  [data-slot="dialog-content"] {
    animation: none;
  }
}

import type { HTMLAttributes } from "react";
import { Button } from "./Button";
import { cn } from "@/lib/utils";

export type DividerAction = {
  label: string;
  onClick?: () => void;
  theme?: "gray" | "blue" | "green" | "red";
  variant?: "solid" | "subtle" | "outline" | "ghost" | "link";
  size?: "xs" | "sm" | "md" | "lg";
  disabled?: boolean;
  loading?: boolean;
};

export type DividerProps = HTMLAttributes<HTMLElement> & {
  /** Direction of the rule. */
  orientation?: "horizontal" | "vertical";
  /** Where a button sits along the rule. Ignored without `action`. */
  align?: "start" | "center" | "end";
  /** Stretch to the cross-axis size of a flex parent. */
  flexItem?: boolean;
  /** Render a button on the rule. */
  action?: DividerAction;
};

export function Divider({
  className,
  orientation = "horizontal",
  align = "center",
  flexItem = false,
  action,
  ...props
}: DividerProps) {
  const flexClass = flexItem ? "self-stretch h-auto" : "h-full";

  if (!action) {
    return (
      <hr
        role="separator"
        aria-orientation={orientation}
        className={cn(
          "border-0 border-outline-gray-2",
          orientation === "horizontal" ? "w-full border-t" : "border-l",
          flexClass,
          className,
        )}
        {...props}
      />
    );
  }

  const { label, onClick, ...buttonProps } = action;
  const isHorizontal = orientation === "horizontal";

  return (
    <div
      className={cn(
        "relative whitespace-nowrap border-0 border-outline-gray-2",
        isHorizontal
          ? cn(
              "flex w-full min-h-7 items-center",
              align === "center" && "justify-center",
              align === "start" && "justify-start pl-4",
              align === "end" && "justify-end pr-4",
            )
          : cn(
              "flex justify-center",
              flexItem ? "self-stretch" : "h-full",
              align === "center" && "items-center",
              align === "start" && "items-start pt-4",
              align === "end" && "items-end pb-4",
            ),
        className,
      )}
      {...props}
    >
      <div
        role="separator"
        aria-orientation={orientation}
        className={cn(
          "absolute border-0 border-outline-gray-2",
          isHorizontal
            ? "inset-x-0 top-1/2 -translate-y-1/2 border-t"
            : "inset-y-0 left-1/2 -translate-x-1/2 border-l",
        )}
      />
      <Button
        {...buttonProps}
        label={label}
        variant={action.variant ?? "outline"}
        size={action.size ?? "sm"}
        onClick={onClick}
        className="relative z-10"
      />
    </div>
  );
}

import type { ReactNode } from "react";
import { Menu as ArkMenu } from "@ark-ui/react/menu";
import { Portal } from "@ark-ui/react/portal";
import { cn } from "@/lib/utils";

export type DropdownMenuItem = {
  /** Row label. */
  label: string;
  /** Icon shown before the label. */
  icon?: ReactNode;
  /** Shortcut shown at the end of the row. */
  shortcut?: string;
  /** Disables the row. */
  disabled?: boolean;
  /** Colors the row as a destructive action. */
  danger?: boolean;
  /** Runs when the row is chosen. */
  onSelect?: () => void;
};

export type DropdownMenuSeparator = {
  /** Marks a divider between rows. */
  type: "separator";
};

export type DropdownMenuGroup = {
  /** Marks a titled group of rows. */
  type: "group";
  /** Group heading. */
  label?: string;
  /** Rows in the group. */
  items: DropdownMenuItem[];
};

export type DropdownMenuEntry = DropdownMenuItem | DropdownMenuSeparator | DropdownMenuGroup;

export type DropdownMenuProps = {
  /** Rows to render. */
  items?: DropdownMenuEntry[];
  /** Element that opens the menu. */
  trigger?: ReactNode;
  /** Edge of the trigger the menu opens on. */
  side?: "top" | "right" | "bottom" | "left";
  /** Position along that edge. */
  align?: "start" | "center" | "end";
  /** Gap between the trigger and the menu, in pixels. */
  offset?: number;
  /** Class applied to the menu panel. */
  className?: string;
  /** Called with the label of the row that was chosen. */
  onSelect?: (label: string) => void;
  /** Custom rows, used instead of `items`. */
  children?: ReactNode;
};

const itemClasses =
  "flex cursor-pointer select-none items-center gap-2 rounded-(--radius-3) px-2 py-1.5 text-sm text-ink-gray-7 outline-none transition-colors data-[highlighted]:bg-surface-gray-3 data-[highlighted]:text-ink-gray-8 data-[disabled]:pointer-events-none data-[disabled]:opacity-50";

export function DropdownMenu({
  items = [],
  trigger,
  side = "bottom",
  align = "start",
  offset = 6,
  className,
  onSelect,
  children,
}: DropdownMenuProps) {
  const placement = (align === "center" ? side : `${side}-${align}`) as
    | "top"
    | "right"
    | "bottom"
    | "left"
    | "top-start"
    | "top-end"
    | "right-start"
    | "right-end"
    | "bottom-start"
    | "bottom-end"
    | "left-start"
    | "left-end";

  return (
    <ArkMenu.Root positioning={{ placement, gutter: offset }} lazyMount unmountOnExit>
      {trigger ? <ArkMenu.Trigger asChild>{trigger}</ArkMenu.Trigger> : null}
      <Portal>
        <ArkMenu.Positioner data-slot="dropdown-positioner" className="[--z-index:50]!">
          <ArkMenu.Content
            data-slot="dropdown-content"
            className={cn(
              "min-w-[190px] rounded-4 border border-outline-gray-2 bg-surface-base p-1 shadow-lg outline-none",
              className,
            )}
          >
            {children ??
              items.map((entry, index) => {
                if ("type" in entry && entry.type === "separator") {
                  return (
                    <ArkMenu.Separator
                      key={`separator-${index}`}
                      data-slot="dropdown-separator"
                      className="my-1 h-px bg-outline-gray-2"
                    />
                  );
                }

                if ("type" in entry && entry.type === "group") {
                  return (
                    <ArkMenu.ItemGroup key={`group-${index}`} data-slot="dropdown-group">
                      {entry.label ? (
                        <ArkMenu.ItemGroupLabel className="px-2 py-1 text-xs text-ink-gray-5">
                          {entry.label}
                        </ArkMenu.ItemGroupLabel>
                      ) : null}
                      {entry.items.map((item) => (
                        <ArkMenu.Item
                          key={item.label}
                          value={item.label}
                          disabled={item.disabled}
                          className={cn(
                            itemClasses,
                            item.danger && "text-ink-red-6 data-[highlighted]:text-ink-red-7",
                          )}
                          onSelect={() => {
                            item.onSelect?.();
                            onSelect?.(item.label);
                          }}
                        >
                          {item.icon ? (
                            <span className="flex size-4 items-center justify-center text-ink-gray-6">
                              {item.icon}
                            </span>
                          ) : null}
                          <ArkMenu.ItemText>{item.label}</ArkMenu.ItemText>
                          {item.shortcut ? (
                            <span className="ms-auto text-xs text-ink-gray-5">
                              {item.shortcut}
                            </span>
                          ) : null}
                        </ArkMenu.Item>
                      ))}
                    </ArkMenu.ItemGroup>
                  );
                }

                const item = entry as { label: string; icon?: ReactNode; shortcut?: string; disabled?: boolean; danger?: boolean; onSelect?: () => void };
                return (
                  <ArkMenu.Item
                    key={item.label}
                    value={item.label}
                    disabled={item.disabled}
                    className={cn(
                      itemClasses,
                      item.danger && "text-ink-red-6 data-[highlighted]:text-ink-red-7",
                    )}
                    onSelect={() => {
                      item.onSelect?.();
                      onSelect?.(item.label);
                    }}
                  >
                    {item.icon ? (
                      <span className="flex size-4 items-center justify-center text-ink-gray-6">
                        {item.icon}
                      </span>
                    ) : null}
                    <ArkMenu.ItemText>{item.label}</ArkMenu.ItemText>
                    {item.shortcut ? (
                      <span className="ms-auto text-xs text-ink-gray-5">{item.shortcut}</span>
                    ) : null}
                  </ArkMenu.Item>
                );
              })}
          </ArkMenu.Content>
        </ArkMenu.Positioner>
      </Portal>
    </ArkMenu.Root>
  );
}

/* Rows highlight on hover and on keyboard focus, which Zag marks the same
   way, so pointer and keyboard users see the same row. */
[data-slot="dropdown-content"] {
  max-height: min(24rem, var(--radix-menu-content-available-height, 24rem));
  overflow-y: auto;
}

import type { ComponentPropsWithoutRef } from "react";
import { cn } from "@/lib/utils";

export type ErrorMessageValue =
  | string
  | string[]
  | (Error & { messages?: string | string[] });

export type ErrorMessageProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** One message, several lines, or an Error. */
  message?: ErrorMessageValue | null;
};

function errorLines(value: ErrorMessageValue | null | undefined): string[] {
  if (!value) return [];
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) return value.filter(Boolean).map(String);
  if (value instanceof Error) {
    const messages = value.messages;
    if (Array.isArray(messages) && messages.length) return messages.filter(Boolean).map(String);
    if (typeof messages === "string" && messages) return [messages];
    return value.message ? [value.message] : [];
  }
  return [String(value)];
}

export function ErrorMessage({ message, className, ...props }: ErrorMessageProps) {
  const lines = errorLines(message);
  if (lines.length === 0) return null;

  return (
    <div
      role="alert"
      className={cn("whitespace-pre-line text-sm text-ink-red-7", className)}
      {...props}
    >
      {lines.map((line, index) => (
        <p key={index}>{line}</p>
      ))}
    </div>
  );
}

import { forwardRef, useRef } from "react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { TextInput } from "./TextInput";
import { Textarea } from "./Textarea";
import { Select } from "./Select";
import { Checkbox } from "./Checkbox";

type FormControlType =
  | "text"
  | "email"
  | "password"
  | "number"
  | "search"
  | "tel"
  | "url"
  | "textarea"
  | "select"
  | "checkbox";

type FormControlSize = "xs" | "sm" | "md" | "lg";
type FormControlVariant = "subtle" | "outline" | "ghost";
type SelectValue = string | number;
type SelectOption =
  | string
  | {
      label: string;
      value: SelectValue;
      disabled?: boolean;
    };

export type FormControlProps = Omit<ComponentPropsWithoutRef<"input">, "size" | "type"> & {
  /** Which control to render. */
  type?: FormControlType;
  /** Visual size of the control. */
  size?: FormControlSize;
  /** Surface treatment; ignored by checkbox. */
  variant?: FormControlVariant;
  /** Label rendered above the control. */
  label?: ReactNode;
  /** Helper text rendered below the control. Hidden when `error` is set. */
  description?: ReactNode;
  /** Error message; marks the control invalid. */
  error?: ReactNode;
  /** Marks the field as required and renders an asterisk. */
  required?: boolean;
  /** Rows for `type="textarea"`. */
  rows?: number;
  /** Options for `type="select"`. */
  options?: SelectOption[];
  /** Called when the selected value changes for `type="select"`. */
  onValueChange?: (value: SelectValue | null) => void;
};

type ControlElement =
  | HTMLInputElement
  | HTMLTextAreaElement
  | HTMLSelectElement
  | HTMLButtonElement;

export const FormControl = forwardRef<HTMLElement, FormControlProps>(
  ({ type = "text", size = "sm", variant = "subtle", options, rows, onValueChange, ...props }, ref) => {
    const controlRef = useRef<ControlElement | null>(null);
    const rest = props as Record<string, unknown>;
    const setControlRef = (node: ControlElement | null) => {
      controlRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    };

    if (type === "textarea") {
      return (
        <Textarea
          ref={setControlRef}
          size={size}
          variant={variant}
          rows={rows}
          {...rest}
        />
      );
    }

    if (type === "select") {
      return (
        <Select
          ref={setControlRef}
          size={size}
          variant={variant}
          options={options}
          onValueChange={onValueChange}
          {...rest}
        />
      );
    }

    if (type === "checkbox") {
      return (
        <Checkbox
          ref={setControlRef}
          size={size === "lg" ? "md" : size}
          {...rest}
        />
      );
    }

    return <TextInput ref={setControlRef} type={type} size={size} variant={variant} {...rest} />;
  },
);

FormControl.displayName = "FormControl";

import { Fragment, useMemo } from "react";
import type { ReactNode } from "react";
import {
  ArrowBigRightDash,
  ArrowBigUp,
  ArrowDown,
  ArrowLeft,
  ArrowRight,
  ArrowUp,
  Command,
  CornerDownLeft,
  Delete,
  Option,
} from "lucide-react";
import { cn } from "@/lib/utils";

export type KeyboardShortcutProps = {
  /** Shortcut combo, e.g. `"Mod+Shift+K"`. `Mod` is Cmd on macOS, Ctrl elsewhere. */
  combo?: string;
  /** Draw the keys as background chips. */
  bg?: boolean;
  /** Draw `+` between keys. `"auto"` only puts it between two text keys. */
  showPlus?: boolean | "auto";
  /** Alternative combos shown after a `/`. */
  altCombos?: string[];
  /** Draw icons for the arrow, Enter, Backspace and Delete keys. */
  useIcons?: boolean;
  /** Content shown when no `combo` is given. */
  children?: ReactNode;
  /** Class applied to the root element. */
  className?: string;
};

type ShortcutPart = {
  type: "cmd" | "ctrl" | "shift" | "alt" | "key";
  display: string;
  spell: string;
  icon: "command" | "shift" | "alt" | "up" | "down" | "left" | "right" | "enter" | "backspace" | "delete" | null;
};

const iconMap = {
  command: Command,
  shift: ArrowBigUp,
  alt: Option,
  up: ArrowUp,
  down: ArrowDown,
  left: ArrowLeft,
  right: ArrowRight,
  enter: CornerDownLeft,
  backspace: Delete,
  delete: ArrowBigRightDash,
};

const namedKeys: Record<string, { display: string; spell: string; icon: ShortcutPart["icon"] }> = {
  enter: { display: "↵", spell: "Enter", icon: "enter" },
  return: { display: "↵", spell: "Enter", icon: "enter" },
  escape: { display: "Esc", spell: "Escape", icon: null },
  esc: { display: "Esc", spell: "Escape", icon: null },
  backspace: { display: "⌫", spell: "Backspace", icon: "backspace" },
  delete: { display: "⌦", spell: "Delete", icon: "delete" },
  del: { display: "⌦", spell: "Delete", icon: "delete" },
  tab: { display: "Tab", spell: "Tab", icon: null },
  space: { display: "Space", spell: "Space", icon: null },
  up: { display: "↑", spell: "Up", icon: "up" },
  arrowup: { display: "↑", spell: "Up", icon: "up" },
  down: { display: "↓", spell: "Down", icon: "down" },
  arrowdown: { display: "↓", spell: "Down", icon: "down" },
  left: { display: "←", spell: "Left", icon: "left" },
  arrowleft: { display: "←", spell: "Left", icon: "left" },
  right: { display: "→", spell: "Right", icon: "right" },
  arrowright: { display: "→", spell: "Right", icon: "right" },
};

function isMacPlatform() {
  if (typeof navigator === "undefined") return false;
  const platform =
    (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData?.platform ??
    navigator.platform ??
    navigator.userAgent;
  return /mac|iphone|ipad|ipod/i.test(platform);
}

function parseCombo(combo: string, isMac: boolean): ShortcutPart[] {
  const parts: ShortcutPart[] = [];
  const tokens = combo
    .split("+")
    .map((token) => token.trim())
    .filter(Boolean);

  for (const token of tokens) {
    const lower = token.toLowerCase();
    if (lower === "mod") {
      parts.push(
        isMac
          ? { type: "cmd", display: "⌘", spell: "Command", icon: "command" }
          : { type: "ctrl", display: "Ctrl", spell: "Control", icon: null },
      );
      continue;
    }
    if (lower === "cmd" || lower === "command" || lower === "meta") {
      parts.push({ type: "cmd", display: "⌘", spell: "Command", icon: "command" });
      continue;
    }
    if (lower === "ctrl" || lower === "control") {
      parts.push({ type: "ctrl", display: "Ctrl", spell: "Control", icon: null });
      continue;
    }
    if (lower === "shift") {
      parts.push({ type: "shift", display: "⇧", spell: "Shift", icon: "shift" });
      continue;
    }
    if (lower === "alt" || lower === "option" || lower === "opt") {
      parts.push({ type: "alt", display: "⌥", spell: "Alt", icon: "alt" });
      continue;
    }
    const named = namedKeys[lower];
    if (named) {
      parts.push({ type: "key", ...named });
      continue;
    }
    const display = token.length === 1 ? token.toUpperCase() : token;
    parts.push({ type: "key", display, spell: display, icon: null });
  }

  return parts;
}

function spellOut(parts: ShortcutPart[]) {
  return parts.map((part) => part.spell).join(" plus ");
}

export function KeyboardShortcut({
  combo,
  bg = false,
  showPlus = "auto",
  altCombos = [],
  useIcons = true,
  children,
  className,
  ...props
}: KeyboardShortcutProps) {
  const isMac = isMacPlatform();
  const parts = useMemo(() => (combo ? parseCombo(combo, isMac) : []), [combo, isMac]);
  const altParts = useMemo(
    () => altCombos.map((alt) => parseCombo(alt, isMac)),
    [altCombos, isMac],
  );

  const uniqueAltParts = useMemo(() => {
    const seen = new Set([parts.map((part) => part.display).join("+")]);
    return altParts.filter((alt) => {
      const key = alt.map((part) => part.display).join("+");
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }, [altParts, parts]);

  const plusAfter = parts.slice(0, -1).map((part, index) => {
    if (showPlus === "auto") {
      const next = parts[index + 1];
      const partDrawsIcon = part.icon !== null || part.type === "cmd" || part.type === "shift" || part.type === "alt";
      const nextDrawsIcon = next.icon !== null || next.type === "cmd" || next.type === "shift" || next.type === "alt";
      return !(partDrawsIcon || nextDrawsIcon);
    }
    return showPlus;
  });

  const ariaLabel = parts.length
    ? `Shortcut ${[spellOut(parts), ...uniqueAltParts.map((alt) => spellOut(alt))].join(", or ")}`
    : undefined;

  function renderPart(part: ShortcutPart, mode: "plain" | "chip") {
    const Icon = part.icon ? iconMap[part.icon] : null;
    const isModifier = part.type === "cmd" || part.type === "shift" || part.type === "alt";
    const showIcon = Boolean(Icon) && (isModifier || useIcons);

    if (mode === "chip") {
      const chipIcon = part.type === "cmd" ? "command" : useIcons ? part.icon : null;
      const ChipIcon = chipIcon ? iconMap[chipIcon] : null;
      return (
        <kbd
          data-slot="key"
          data-key-type={part.type}
          className="inline-flex h-6 min-w-[1.5rem] items-center justify-center rounded-4 bg-surface-gray-2 px-1.5 text-xs-medium text-ink-gray-7"
        >
          {ChipIcon ? <ChipIcon aria-hidden="true" className="size-3" /> : part.display}
        </kbd>
      );
    }

    return (
      <span data-slot="key" data-key-type={part.type}>
        {showIcon && Icon ? (
          <Icon aria-hidden="true" className="size-3" />
        ) : (
          <span className="leading-none uppercase">{part.display}</span>
        )}
      </span>
    );
  }

  if (!parts.length) {
    return (
      <span
        data-slot="keyboard-shortcut"
        className={cn("inline-flex items-center gap-0.5 text-sm text-ink-gray-5", className)}
        {...props}
      >
        {children}
      </span>
    );
  }

  return (
    <span
      data-slot="keyboard-shortcut"
      data-bg={bg ? "true" : undefined}
      aria-label={ariaLabel}
      role={ariaLabel ? "img" : undefined}
      className={cn("inline-flex items-center gap-0.5", !bg && "text-sm text-ink-gray-5", className)}
      {...props}
    >
      {parts.map((part, index) => (
        <Fragment key={`${part.type}-${part.display}-${index}`}>
          {renderPart(part, bg ? "chip" : "plain")}
          {plusAfter[index] ? (
            <span
              data-slot="separator"
              aria-hidden="true"
              className="font-mono text-[10px] leading-none opacity-60"
            >
              +
            </span>
          ) : null}
        </Fragment>
      ))}
      {uniqueAltParts.length ? (
        <span data-slot="alt-combos" className="ms-1 inline-flex items-center gap-1.5">
          {uniqueAltParts.map((alt, altIndex) => (
            <Fragment key={`alt-${altIndex}`}>
              <span aria-hidden="true" className="text-xs text-ink-gray-4">
                /
              </span>
              <span className="inline-flex items-center gap-0.5">
                {alt.map((part, index) => (
                  <Fragment key={`${part.type}-${part.display}-${index}`}>
                    {renderPart(part, bg ? "chip" : "plain")}
                  </Fragment>
                ))}
              </span>
            </Fragment>
          ))}
        </span>
      ) : null}
    </span>
  );
}

/* Key chips keep their own baseline so a row of them reads as one line. */
[data-slot="keyboard-shortcut"] kbd {
  font-family: inherit;
}

import { forwardRef } from "react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";
export type LabelProps = ComponentPropsWithoutRef<"label"> & {
  disabled?: boolean;
  /** Text content of the label. Children take precedence. */
  label?: ReactNode;
  /** Marks the field as required with a red asterisk and hidden text. */
  required?: boolean;
};
export const Label = forwardRef<HTMLLabelElement, LabelProps>(
  ({ className, disabled, label, required, children, ...props }, ref) => {
    return (
      <label
        ref={ref}
        data-disabled={disabled || undefined}
        className={cn(
          "block [font-size:var(--label-font-size)] font-(--label-font-weight) leading-tighter text-(--label-color) data-[disabled]:cursor-not-allowed data-[disabled]:text-(--label-disabled-color)",
          className,
        )}
        {...props}
      >
        {children ?? label}
        {required ? (
          <>
            <span className="ms-0.5 select-none text-(--label-required-color)" aria-hidden="true">
              *
            </span>
            <span className="sr-only">(required)</span>
          </>
        ) : null}
      </label>
    );
  },
);

Label.displayName = "Label";

/* Label component tokens — mirrors frappe-ui v1 FormLabel. */
:root {
  --label-font-size: 13px;
  --label-font-weight: 420;
  --label-color: var(--ink-gray-6);
  --label-disabled-color: var(--ink-gray-4);
  --label-required-color: var(--ink-red-5);
}

import type { HTMLAttributes } from "react";
import { Spinner } from "./Spinner";
import { cn } from "@/lib/utils";

export type LoadingTextProps = HTMLAttributes<HTMLDivElement> & {
  /** Text shown next to the spinner. */
  text?: string;
};

export function LoadingText({
  text = "Loading...",
  className,
  ...props
}: LoadingTextProps) {
  return (
    <div
      data-slot="loading-text"
      className={cn("flex items-center text-base text-ink-gray-4", className)}
      {...props}
    >
      <Spinner size="xs" className="-ml-1 mr-2" />
      {text}
    </div>
  );
}

/* The spinner sits on the text baseline; the negative start margin pulls it
   into the line so the row reads as one line of text. */
[data-slot="loading-text"] {
  line-height: 1;
}

import { useState } from "react";
import type { ReactNode } from "react";
import { Popover as ArkPopover } from "@ark-ui/react/popover";
import { Portal } from "@ark-ui/react/portal";
import { cn } from "@/lib/utils";

export type PopoverSide = "top" | "right" | "bottom" | "left";
export type PopoverAlign = "start" | "center" | "end";

export type PopoverProps = {
  /** Whether the panel is open. Omit for uncontrolled use. */
  open?: boolean;
  /** Initially open, for uncontrolled use. */
  defaultOpen?: boolean;
  /** Called when the panel opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** Edge of the trigger the panel opens on. */
  side?: PopoverSide;
  /** Position along that edge. */
  align?: PopoverAlign;
  /** Gap between the trigger and the panel, in pixels. */
  offset?: number;
  /** Space kept from the viewport edge. */
  collisionPadding?: number;
  /** Close on an outside click and on Escape. */
  dismissible?: boolean;
  /** Move focus into the panel when it opens. */
  autoFocus?: boolean;
  /** Make the panel at least as wide as the trigger. */
  matchTriggerWidth?: boolean;
  /** Drop the panel surface, so the content draws its own. */
  bare?: boolean;
  /** Draw an arrow pointing back at the trigger. */
  arrow?: boolean;
  /** Element that opens the panel. */
  trigger?: ReactNode;
  /** Panel content. */
  children?: ReactNode;
  /** Class applied to the panel. */
  className?: string;
};

export function Popover({
  open,
  defaultOpen = false,
  onOpenChange,
  side = "bottom",
  align = "center",
  offset = 8,
  collisionPadding = 8,
  dismissible = true,
  autoFocus = true,
  matchTriggerWidth = false,
  bare = false,
  arrow = false,
  trigger,
  children,
  className,
}: PopoverProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const isControlled = open !== undefined;
  const isOpen = isControlled ? open : internalOpen;

  const placement = (align === "center" ? side : `${side}-${align}`) as
    | "top"
    | "right"
    | "bottom"
    | "left"
    | "top-start"
    | "top-end"
    | "right-start"
    | "right-end"
    | "bottom-start"
    | "bottom-end"
    | "left-start"
    | "left-end";

  function setOpen(next: boolean) {
    if (!isControlled) setInternalOpen(next);
    onOpenChange?.(next);
  }

  return (
    <ArkPopover.Root
      open={isOpen}
      onOpenChange={(details) => setOpen(details.open)}
      autoFocus={autoFocus}
      closeOnInteractOutside={dismissible}
      closeOnEscape={dismissible}
      positioning={{ placement, gutter: offset, overflowPadding: collisionPadding }}
      lazyMount
      unmountOnExit
    >
      {trigger ? <ArkPopover.Trigger asChild>{trigger}</ArkPopover.Trigger> : null}
      <Portal>
        <ArkPopover.Positioner
          data-slot="popover-positioner"
          className="[--z-index:50]!"
          style={{ minWidth: matchTriggerWidth ? "var(--reference-width)" : undefined }}
        >
          <ArkPopover.Content
            data-slot="popover-content"
            className={cn(
              "rounded-4 border border-outline-gray-2 bg-surface-base p-3 shadow-lg outline-none",
              bare && "border-0 bg-transparent p-0 shadow-none",
              className,
            )}
          >
            {children}
            {arrow ? (
              <ArkPopover.Arrow data-slot="popover-arrow" className="text-surface-base">
                <ArkPopover.ArrowTip
                  data-slot="popover-arrow-tip"
                  className="size-2 rotate-45 rounded-[2px] border border-outline-gray-2 bg-surface-base"
                />
              </ArkPopover.Arrow>
            ) : null}
          </ArkPopover.Content>
        </ArkPopover.Positioner>
      </Portal>
    </ArkPopover.Root>
  );
}

/* The panel fades and lifts a little as it opens. */
@keyframes espresso-popover-in {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

[data-slot="popover-content"][data-state="open"] {
  animation: espresso-popover-in 140ms cubic-bezier(0.23, 1, 0.32, 1);
  transform-origin: var(--transform-origin);
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="popover-content"][data-state="open"] {
    animation: none;
  }
}

import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { useId } from "react";
import { cn } from "@/lib/utils";

const sizeClasses = {
  sm: "h-(--progress-sm-height)",
  md: "h-(--progress-md-height)",
  lg: "h-(--progress-lg-height)",
  xl: "h-(--progress-xl-height)",
};

type ProgressSize = keyof typeof sizeClasses;

export type ProgressProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** Current value from 0 to 100. */
  value: number;
  /** Height of the bar. */
  size?: ProgressSize;
  /** Label shown above the bar. */
  label?: ReactNode;
  /** `true` shows the percentage; pass content to replace it. */
  hint?: boolean | ReactNode;
  /** Splits the bar into whole segments. */
  intervals?: number;
};

export function Progress({
  className,
  value,
  size = "sm",
  label,
  hint,
  intervals,
  ...props
}: ProgressProps) {
  const labelId = useId();
  const clamped = Math.min(Math.max(Number(value), 0), 100);
  const showHint =
    hint === true || (hint !== undefined && hint !== false && hint !== null);
  const hasHeader = Boolean(label) || showHint;
  const filledIntervals = intervals ? Math.round((clamped / 100) * intervals) : 0;
  const barClasses = cn("transform-gpu overflow-hidden rounded-(--progress-radius)", sizeClasses[size]);
  const ariaLabel = typeof label === "string" ? label : "Progress";

  return (
    <div className={cn("w-full space-y-2.5", className)}>
      {hasHeader ? (
        <div className="flex items-baseline justify-between gap-4">
          {label ? (
            <span id={labelId} className="text-sm font-medium text-ink-gray-8">
              {label}
            </span>
          ) : (
            <span />
          )}
          {showHint ? (
            <span className="text-sm font-medium text-ink-gray-4">
              {hint === true || hint === undefined ? `${clamped}%` : hint}
            </span>
          ) : null}
        </div>
      ) : null}
      <div
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={clamped}
        aria-label={label ? undefined : ariaLabel}
        aria-labelledby={label ? labelId : undefined}
        data-slot="progress"
        data-size={size}
        className={cn(barClasses, intervals ? "flex gap-(--progress-gap)" : "bg-surface-gray-2")}
        {...props}
      >
        {intervals ? (
          Array.from({ length: intervals }, (_, index) => (
            <div
              key={index}
              className={cn(
                "h-full w-full",
                index < filledIntervals ? "bg-surface-gray-10" : "bg-surface-gray-2",
              )}
            />
          ))
        ) : (
          <div
            className="h-full w-full bg-surface-gray-10 transition-transform [transition-duration:var(--progress-transition-duration)] [transition-timing-function:var(--progress-ease)] motion-reduce:transition-none"
            style={{ transform: `translateX(${clamped - 100}%)` }}
          />
        )}
      </div>
    </div>
  );
}

/* Progress component tokens. */
:root {
  --progress-sm-height: 2px;
  --progress-md-height: 4px;
  --progress-lg-height: 8px;
  --progress-xl-height: 12px;
  --progress-radius: var(--radius-7);
  --progress-gap: 4px;
  --progress-transition-duration: 660ms;
  --progress-ease: cubic-bezier(0.65, 0, 0.35, 1);
}

import { forwardRef, useContext, useId } from "react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { RadioGroupContext } from "./RadioGroup";
import type { RadioValue } from "./RadioGroup";

const sizeClasses = {
  xs: {
    circle: "size-(--radio-xs-size)",
    selected: "[border-width:var(--radio-xs-checked-border)]",
    offset: "[margin-top:var(--radio-xs-offset)]",
  },
  sm: {
    circle: "size-(--radio-sm-size)",
    selected: "[border-width:var(--radio-sm-checked-border)]",
    offset: "[margin-top:var(--radio-sm-offset)]",
  },
  md: {
    circle: "size-(--radio-md-size)",
    selected: "[border-width:var(--radio-md-checked-border)]",
    offset: "[margin-top:var(--radio-md-offset)]",
  },
};

export type RadioProps = Omit<ComponentPropsWithoutRef<"label">, "onChange"> & {
  /** Value this option represents inside its RadioGroup. */
  value: RadioValue;
  /** Label rendered beside the control. */
  label?: ReactNode;
  /** Description rendered below the label. */
  description?: ReactNode;
  /** Disables this option only. */
  disabled?: boolean;
};

export const Radio = forwardRef<HTMLInputElement, RadioProps>(
  ({ className, id, value, label, description, disabled, ...props }, ref) => {
    const group = useContext(RadioGroupContext);
    if (!group) {
      throw new Error("[espresso-ui] <Radio> must be used inside a <RadioGroup>.");
    }

    const generatedId = useId();
    const inputId = id ?? generatedId;
    const labelId = `${inputId}-label`;
    const descriptionId = `${inputId}-description`;
    const hasLabel = Boolean(label);
    const hasDescription = Boolean(description);
    const isDisabled = group.disabled || Boolean(disabled);
    const isSelected = group.value === value;
    const sizing = sizeClasses[group.size];
    const padded = group.padded;

    const rowClasses = cn(
      "group flex items-start gap-2 rounded-(--radio-padded-radius) text-start transition-colors [&:has(:focus-visible)]:ring-2 [&:has(:focus-visible)]:ring-ink-gray-8 [&:has(:focus-visible)]:ring-offset-2 [&:has(:focus-visible)]:ring-offset-surface-base",
      isDisabled ? "cursor-not-allowed" : "cursor-pointer",
      padded && !isDisabled && "hover:bg-surface-gray-3 active:bg-surface-gray-4",
      padded &&
        (hasDescription
          ? group.size === "md"
            ? "px-3 py-2"
            : "px-1.5 py-1.5"
          : group.size === "md"
            ? "h-8 items-center px-3"
            : group.size === "sm"
              ? "h-7 items-center px-1.5"
              : "h-6 items-center px-1.5"),
      className,
    );

    const circleClasses = cn(
      "box-border shrink-0 rounded-full transition-colors",
      sizing.circle,
      isSelected ? sizing.selected : "border",
      hasDescription || !padded ? sizing.offset : "",
      isDisabled
        ? isSelected
          ? "bg-surface-base border-[color:var(--surface-gray-5)]"
          : "bg-surface-base border-outline-gray-3"
        : isSelected
          ? "bg-surface-base border-[color:var(--surface-gray-10)] group-hover:border-[color:var(--surface-gray-9)] group-active:border-[color:var(--surface-gray-8)]"
          : "bg-surface-base border-outline-gray-4 group-hover:border-outline-gray-5 group-active:border-outline-gray-6",
    );

    return (
      <label
        htmlFor={inputId}
        data-slot="control"
        data-state={isSelected ? "checked" : "unchecked"}
        data-size={group.size}
        data-disabled={isDisabled ? "true" : undefined}
        className={rowClasses}
        {...props}
      >
        <input
          ref={ref}
          id={inputId}
          type="radio"
          name={group.name}
          value={String(value)}
          checked={isSelected}
          disabled={isDisabled}
          required={group.required}
          aria-required={group.required || undefined}
          aria-labelledby={hasLabel ? labelId : undefined}
          aria-describedby={hasDescription ? descriptionId : undefined}
          aria-invalid={group.hasError || undefined}
          aria-errormessage={group.hasError ? group.errorId : undefined}
          className="peer sr-only"
          data-slot="input"
          onChange={() => group.onSelect(value)}
        />
        <span className={circleClasses} aria-hidden="true" />
        <span className="flex flex-col items-start gap-0.5 text-start">
          {hasLabel ? (
            <span
              id={labelId}
              data-slot="label"
              className={cn(
                "block select-none text-base leading-normal",
                isDisabled ? "text-ink-gray-4" : "text-ink-gray-7",
              )}
            >
              {label}
            </span>
          ) : null}
          {hasDescription ? (
            <span
              id={descriptionId}
              data-slot="description"
              className={cn(
                "block select-none text-sm leading-normal",
                isDisabled ? "text-ink-gray-3" : "text-ink-gray-5",
              )}
            >
              {description}
            </span>
          ) : null}
        </span>
      </label>
    );
  },
);

Radio.displayName = "Radio";

import { createContext, forwardRef, useId, useState } from "react";
import type { ComponentPropsWithoutRef, KeyboardEvent, ReactNode } from "react";
import { cn } from "@/lib/utils";

type RadioSize = "xs" | "sm" | "md";
type RadioOrientation = "vertical" | "horizontal";
export type RadioValue = string | number | boolean;
export type RadioGroupError =
  | string
  | string[]
  | (Error & { messages?: string | string[] })
  | null;

export type RadioGroupProps = Omit<
  ComponentPropsWithoutRef<"div">,
  "onChange" | "defaultValue"
> & {
  /** Selected value. Omit for uncontrolled use. */
  value?: RadioValue;
  /** Initial value for uncontrolled use. */
  defaultValue?: RadioValue;
  /** Called when the selected value changes. */
  onValueChange?: (value: RadioValue) => void;
  /** Size of every radio in the group. */
  size?: RadioSize;
  /** Wraps each option in a clickable surface. */
  padded?: boolean;
  /** Disables every radio in the group. */
  disabled?: boolean;
  /** Layout and arrow-key axis. */
  orientation?: RadioOrientation;
  /** Keeps arrow-key navigation inside the group. Native radios loop by default. */
  loop?: boolean;
  /** Native form name for the group. */
  name?: string;
  /** Group label rendered above the options. */
  label?: ReactNode;
  /** Group description rendered below the options. Hidden when `error` is set. */
  description?: ReactNode;
  /** Group error message. Accepts a string, lines, or an Error. */
  error?: RadioGroupError;
  /** Marks the group as required and renders an asterisk. */
  required?: boolean;
};

export type RadioGroupContextValue = {
  name: string;
  value: RadioValue | undefined;
  size: RadioSize;
  padded: boolean;
  disabled: boolean;
  required: boolean;
  hasError: boolean;
  errorId: string;
  onSelect: (value: RadioValue) => void;
};

export const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);

function linesOf(value: RadioGroupError | undefined): string[] {
  if (!value) return [];
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) return value.filter(Boolean).map(String);
  if (value instanceof Error) {
    const messages = value.messages;
    if (Array.isArray(messages) && messages.length) return messages.filter(Boolean).map(String);
    if (typeof messages === "string" && messages) return [messages];
    return value.message ? [value.message] : [];
  }
  return [String(value)];
}

const requiredMark = (
  <>
    <span className="select-none [color:var(--label-required-color,var(--ink-red-5))]" aria-hidden="true">
      *
    </span>
    <span className="sr-only">(required)</span>
  </>
);

export const RadioGroup = forwardRef<HTMLDivElement, RadioGroupProps>(
  (
    {
      className,
      children,
      id,
      value,
      defaultValue,
      onValueChange,
      size = "sm",
      padded = false,
      disabled = false,
      orientation = "vertical",
      loop = true,
      name,
      label,
      description,
      error,
      required,
      "aria-describedby": ariaDescribedBy,
      ...props
    },
    ref,
  ) => {
    const generatedId = useId();
    const groupId = id ?? generatedId;
    const labelId = `${groupId}-label`;
    const descriptionId = `${groupId}-description`;
    const errorId = `${groupId}-error`;
    const generatedName = useId();
    const groupName = name ?? `radio-group-${generatedName.replace(/:/g, "")}`;
    const [internalValue, setInternalValue] = useState(defaultValue);
    const isControlled = value !== undefined;
    const currentValue = isControlled ? value : internalValue;
    const errorLines = linesOf(error);
    const hasError = errorLines.length > 0;
    const hasLabel = Boolean(label);
    const stacked = orientation === "vertical";
    const describedBy =
      [
        description && !hasError ? descriptionId : null,
        hasError ? errorId : null,
        ariaDescribedBy,
      ]
        .filter(Boolean)
        .join(" ") || undefined;

    const select = (next: RadioValue) => {
      if (!isControlled) setInternalValue(next);
      onValueChange?.(next);
    };

    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
      if (loop) return;
      const forward = orientation === "vertical" ? event.key === "ArrowDown" : event.key === "ArrowRight";
      const backward = orientation === "vertical" ? event.key === "ArrowUp" : event.key === "ArrowLeft";
      if (!forward && !backward) return;
      const radios = Array.from(
        event.currentTarget.querySelectorAll<HTMLInputElement>('input[type="radio"]:not(:disabled)'),
      );
      const index = radios.indexOf(document.activeElement as HTMLInputElement);
      if (index < 0) return;
      if ((forward && index === radios.length - 1) || (backward && index === 0)) {
        event.preventDefault();
      }
    };

    return (
      <div className={cn("flex flex-col", className)}>
        {hasLabel ? (
          <div
            id={labelId}
            className="block [font-size:var(--label-font-size,13px)] [font-weight:var(--label-font-weight,420)] leading-tighter [color:var(--label-color,var(--ink-gray-6))]"
          >
            {label}
            {required ? requiredMark : null}
          </div>
        ) : null}
        <div
          ref={ref}
          id={groupId}
          role="radiogroup"
          aria-labelledby={hasLabel ? labelId : undefined}
          aria-describedby={describedBy}
          aria-required={required || undefined}
          aria-orientation={orientation}
          aria-invalid={hasError || undefined}
          aria-errormessage={hasError ? errorId : undefined}
          data-slot="group"
          data-size={size}
          data-padded={padded ? "true" : undefined}
          data-orientation={orientation}
          data-disabled={disabled ? "true" : undefined}
          data-loop={loop ? "true" : "false"}
          onKeyDown={handleKeyDown}
          className={cn(
            "flex",
            stacked ? "flex-col" : "flex-row flex-wrap items-center",
            padded ? "" : stacked ? "gap-y-1.5" : "gap-x-4",
            hasLabel ? "mt-1.5" : "",
          )}
          {...props}
        >
          <RadioGroupContext.Provider
            value={{
              name: groupName,
              value: currentValue,
              size,
              padded,
              disabled,
              required: Boolean(required),
              hasError,
              errorId,
              onSelect: select,
            }}
          >
            {children}
          </RadioGroupContext.Provider>
        </div>
        {description && !hasError ? (
          <p
            id={descriptionId}
            className="mt-1 [font-size:var(--input-description-font-size)] leading-tighter text-ink-gray-5"
          >
            {description}
          </p>
        ) : null}
        {hasError ? (
          <div
            id={errorId}
            role="alert"
            className="mt-1 [font-size:var(--input-description-font-size)] leading-tighter text-ink-red-7"
          >
            {errorLines.map((line, index) => (
              <p key={index}>{line}</p>
            ))}
          </div>
        ) : null}
      </div>
    );
  },
);

RadioGroup.displayName = "RadioGroup";

/* RadioGroup and Radio tokens — frappe-ui v1 control geometry. */
:root {
  /* Control diameter: xs 13px / sm 14px / md 16px */
  --radio-xs-size: 13px;
  --radio-sm-size: 14px;
  --radio-md-size: 16px;

  /* Selected ring width leaves a surface-base hole in the centre. */
  --radio-xs-checked-border: 3.7px;
  --radio-sm-checked-border: 4px;
  --radio-md-checked-border: 4.5px;

  /* Optical offset from the first line of the label. */
  --radio-xs-offset: 4px;
  --radio-sm-offset: 3.5px;
  --radio-md-offset: 2.5px;

  --radio-padded-radius: var(--radius-4);
}

import {
  useId,
  useRef,
  useState,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";
import { ErrorMessage } from "./ErrorMessage";
import { Label } from "./Label";

export type RatingSize = "xs" | "sm" | "md" | "lg";
export type RatingStep = 1 | 0.5;
export type RatingStarState = "filled" | "preview" | "removing" | "empty";
export type RatingError = string | string[] | (Error & { messages?: string | string[] }) | null;

export type RatingIconProps = {
  index: number;
  side: "left" | "right";
  state: RatingStarState;
  leftState: RatingStarState;
  rightState: RatingStarState;
  value: number;
  previewValue: number | null;
  max: number;
};

export type RatingProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  /** Current rating from 0 to `max`. Omit for uncontrolled use. */
  value?: number;
  /** Initial rating for uncontrolled use. */
  defaultValue?: number;
  /** Called when the rating changes. */
  onValueChange?: (value: number) => void;
  /** Number of stars. Defaults to 5. */
  max?: number;
  /** Whole or half stars. */
  step?: RatingStep;
  /** Disables every star. */
  disabled?: boolean;
  /** Star size. */
  size?: RatingSize;
  /** Label rendered above the stars. */
  label?: ReactNode;
  /** Supporting text rendered below the stars. Hidden when `error` is set. */
  description?: ReactNode;
  /** Error text, lines, or an Error. */
  error?: RatingError;
  /** Marks the rating as required. */
  required?: boolean;
  /** A class name or custom icon, or a render function called per half. */
  icon?: ReactNode | ((props: RatingIconProps) => ReactNode);
};

const sizeClasses = {
  xs: "size-3.5",
  sm: "size-4",
  md: "size-5",
  lg: "size-6",
};

const colorClasses = {
  filled: "text-ink-amber-6",
  preview: "text-ink-amber-3",
  removing: "text-ink-amber-4",
  empty: "text-outline-gray-3",
};

function errorPresent(error: RatingError | undefined) {
  if (!error) return false;
  if (Array.isArray(error)) return error.filter(Boolean).length > 0;
  if (error instanceof Error) return Boolean(error.message);
  return Boolean(error);
}

function StarGlyph({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="currentColor"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={className}
    >
      <path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z" />
    </svg>
  );
}

export function Rating({
  value,
  defaultValue = 0,
  onValueChange,
  max = 5,
  step = 1,
  disabled = false,
  size = "sm",
  label,
  description,
  error,
  required = false,
  icon,
  className,
  ...props
}: RatingProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [hovered, setHovered] = useState<number | null>(null);
  const [focused, setFocused] = useState(1);
  const groupRef = useRef<HTMLDivElement>(null);
  const baseId = useId();
  const labelId = `${baseId}-label`;
  const descriptionId = `${baseId}-description`;
  const errorId = `${baseId}-error`;
  const hasError = errorPresent(error);
  const hasLabeling = Boolean(label || description || hasError);
  const isSlider = step === 0.5;

  const current = Math.max(0, Math.min(max, value !== undefined ? value : internalValue));
  const saved = Math.round(current / step) * step;

  function setValue(next: number) {
    const clamped = Math.max(0, Math.min(max, Math.round(next / step) * step));
    if (value === undefined) setInternalValue(clamped);
    onValueChange?.(clamped);
  }

  function halfState(half: number): RatingStarState {
    if (hovered === null) return half <= saved ? "filled" : "empty";
    if (half <= Math.min(saved, hovered)) return "filled";
    if (half <= hovered) return "preview";
    if (half <= saved) return "removing";
    return "empty";
  }

  function hitValue(event: { currentTarget: HTMLElement; clientX: number }, index: number) {
    if (step !== 0.5) return index;
    const rect = event.currentTarget.getBoundingClientRect();
    return event.clientX - rect.left < rect.width / 2 ? index - 0.5 : index;
  }

  function commit(next: number) {
    const candidate = Math.max(0, Math.min(max, Math.round(next / step) * step));
    setValue(candidate === saved ? 0 : candidate);
  }

  function focusStar(index: number) {
    setFocused(index);
    requestAnimationFrame(() => {
      groupRef.current?.querySelector<HTMLButtonElement>(`[data-index="${index}"]`)?.focus();
    });
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (disabled) return;
    const key = event.key;

    if (isSlider) {
      let next: number | null = null;
      if (key === "ArrowRight" || key === "ArrowUp") next = Math.min(max, saved + step);
      else if (key === "ArrowLeft" || key === "ArrowDown") next = Math.max(0, saved - step);
      else if (key === "Home") next = 0;
      else if (key === "End") next = max;
      else if (key === "PageUp") next = Math.min(max, saved + 1);
      else if (key === "PageDown") next = Math.max(0, saved - 1);
      else if (/^[0-9]$/.test(key)) next = Math.min(max, Number(key));
      if (next !== null) {
        event.preventDefault();
        setValue(next);
      }
      return;
    }

    const active = focused || Math.max(1, Math.min(max, Math.ceil(saved) || 1));
    let next: number | null = null;
    if (key === "ArrowRight" || key === "ArrowDown") next = Math.min(max, active + 1);
    else if (key === "ArrowLeft" || key === "ArrowUp") next = Math.max(1, active - 1);
    else if (key === "Home") next = 1;
    else if (key === "End") next = max;
    else if (key === " " || key === "Enter") next = active;
    else if (/^[0-9]$/.test(key)) {
      event.preventDefault();
      setValue(key === "0" ? 0 : Math.min(max, Number(key)));
      return;
    }
    if (next !== null) {
      event.preventDefault();
      setValue(next);
      focusStar(next);
    }
  }

  function renderIcon(index: number, side: "left" | "right") {
    const state = halfState(side === "left" ? index - 0.5 : index);
    const iconProps = {
      index,
      side,
      state,
      leftState: halfState(index - 0.5),
      rightState: halfState(index),
      value: saved,
      previewValue: hovered,
      max,
    };

    if (typeof icon === "function") return icon(iconProps);
    if (typeof icon === "string") return <span className={cn(icon, "size-full")} aria-hidden="true" />;
    if (icon) return icon;
    return <StarGlyph className="size-full" />;
  }

  const starCount = Math.max(1, max);

  return (
    <div
      data-slot="rating"
      data-size={size}
      className={cn(hasLabeling && "space-y-1", className)}
      {...props}
    >
      {label ? (
        <Label id={labelId} required={required}>
          {label}
        </Label>
      ) : null}
      <div
        ref={groupRef}
        id={`${baseId}-control`}
        role={isSlider ? "slider" : "radiogroup"}
        aria-labelledby={label ? labelId : undefined}
        aria-describedby={
          [description && !hasError ? descriptionId : undefined, hasError ? errorId : undefined]
            .filter(Boolean)
            .join(" ") || undefined
        }
        aria-errormessage={hasError ? errorId : undefined}
        aria-invalid={hasError || undefined}
        aria-required={!isSlider && required ? true : undefined}
        aria-disabled={disabled || undefined}
        aria-orientation={isSlider ? "horizontal" : undefined}
        aria-valuemin={isSlider ? 0 : undefined}
        aria-valuemax={isSlider ? max : undefined}
        aria-valuenow={isSlider ? saved : undefined}
        aria-valuetext={
          isSlider
            ? saved === 0
              ? `No rating, out of ${max} stars`
              : `${saved % 1 === 0 ? saved : saved.toFixed(1)} of ${max} stars`
            : undefined
        }
        tabIndex={isSlider ? (disabled ? -1 : 0) : undefined}
        data-slot="control"
        className={cn(
          "inline-flex shrink-0 items-center gap-0.5 rounded-(--radius-1) leading-none outline-none focus-visible:ring-2 focus-visible:ring-outline-gray-4",
          disabled ? "cursor-default" : "cursor-pointer",
        )}
        onPointerLeave={() => setHovered(null)}
        onKeyDown={handleKeyDown}
      >
        {Array.from({ length: starCount }, (_, i) => i + 1).map((index) => {
          const selected = index === saved;
          const tabbable = isSlider ? -1 : disabled ? -1 : index === (Math.ceil(saved) || 1) ? 0 : -1;
          return (
            <button
              key={index}
              type="button"
              role={isSlider ? undefined : "radio"}
              aria-checked={isSlider ? undefined : selected}
              aria-posinset={isSlider ? undefined : index}
              aria-setsize={isSlider ? undefined : starCount}
              aria-label={isSlider ? undefined : `${index} of ${starCount}`}
              data-slot="star"
              data-index={index}
              data-state={halfState(index)}
              tabIndex={tabbable}
              disabled={disabled && !isSlider}
              className={cn(
                "relative inline-flex shrink-0 rounded-(--radius-1) outline-none focus-visible:ring-2 focus-visible:ring-outline-gray-4",
                sizeClasses[size],
                disabled ? "cursor-default" : "cursor-pointer",
              )}
              onPointerMove={(event) => !disabled && setHovered(hitValue(event, index))}
              onClick={(event) => !disabled && commit(hitValue(event, index))}
              onFocus={() => setFocused(index)}
            >
              <span
                data-slot="half-left"
                aria-hidden="true"
                className={cn("absolute inset-0 inline-flex items-center justify-center", colorClasses[halfState(index - 0.5)])}
              >
                {renderIcon(index, "left")}
              </span>
              <span
                data-slot="half-right"
                aria-hidden="true"
                className={cn("absolute inset-0 inline-flex items-center justify-center", colorClasses[halfState(index)])}
              >
                {renderIcon(index, "right")}
              </span>
            </button>
          );
        })}
      </div>
      {description && !hasError ? (
        <p id={descriptionId} className="text-sm text-ink-gray-5">
          {description}
        </p>
      ) : null}
      {hasError ? <ErrorMessage id={errorId} message={error} /> : null}
    </div>
  );
}

/* Each star is drawn twice, clipped at the midline, so half stars work. */
[data-slot="star"] {
  background: transparent;
  padding: 0;
  border: 0;
}

[data-slot="half-left"] {
  clip-path: inset(0 50% 0 0);
}

[data-slot="half-right"] {
  clip-path: inset(0 0 0 50%);
}

import { forwardRef, useEffect, useId, useRef, useState } from "react";
import { ChevronDown } from "lucide-react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

const sizeClasses = {
  xs: "h-(--input-xs-height) rounded-(--input-xs-radius) [font-size:var(--input-xs-font-size)]",
  sm: "h-(--input-sm-height) rounded-(--input-sm-radius) [font-size:var(--input-sm-font-size)]",
  md: "h-(--input-md-height) rounded-(--input-md-radius) [font-size:var(--input-md-font-size)]",
  lg: "h-(--input-lg-height) rounded-(--input-lg-radius) [font-size:var(--input-lg-font-size)]",
};

const paddingClasses = {
  xs: { plain: "ps-1.5", withPrefix: "ps-7" },
  sm: { plain: "ps-2", withPrefix: "ps-8" },
  md: { plain: "ps-2.5", withPrefix: "ps-9" },
  lg: { plain: "ps-3", withPrefix: "ps-10" },
};

const prefixPadding = {
  xs: "ps-1.5",
  sm: "ps-2",
  md: "ps-2.5",
  lg: "ps-3",
};

const suffixPadding = {
  xs: "pe-1.5",
  sm: "pe-2",
  md: "pe-2.5",
  lg: "pe-3",
};

const variantClasses = {
  subtle:
    "border-surface-gray-2 bg-surface-gray-2 hover:border-outline-elevation-2 hover:bg-surface-gray-3 focus:border-outline-gray-4 focus:bg-surface-base focus:shadow-sm",
  outline:
    "border-outline-gray-2 bg-surface-base hover:border-outline-gray-3 hover:shadow-sm focus:border-outline-gray-4 focus:bg-surface-base focus:shadow-sm",
  ghost:
    "border-transparent bg-transparent focus-visible:ring-2 focus-visible:ring-ink-gray-8 focus-visible:ring-offset-2 focus-visible:ring-offset-surface-base",
};

const chevronSizeClasses = {
  xs: "size-3",
  sm: "size-3.5",
  md: "size-4",
  lg: "size-4",
};

const requiredMark = (
  <>
    <span className="select-none [color:var(--label-required-color,var(--ink-red-5))]" aria-hidden="true">
      *
    </span>
    <span className="sr-only">(required)</span>
  </>
);

type SelectSize = keyof typeof sizeClasses;
type SelectVariant = keyof typeof variantClasses;
export type SelectValue = string | number;
export type SelectOption =
  | string
  | {
      label: string;
      value: SelectValue;
      disabled?: boolean;
    };

export type SelectProps = Omit<
  ComponentPropsWithoutRef<"select">,
  "size" | "value" | "defaultValue"
> & {
  /** Visual size of the select. */
  size?: SelectSize;
  /** Surface treatment of the select. */
  variant?: SelectVariant;
  /** Options as strings or `{ label, value, disabled }` objects. */
  options?: SelectOption[];
  /** Selected value. Omit for uncontrolled use. */
  value?: SelectValue | null;
  /** Initial value for uncontrolled use. */
  defaultValue?: SelectValue | null;
  /** Called with the selected value, or `null` when the placeholder is chosen. */
  onValueChange?: (value: SelectValue | null) => void;
  /** Text shown when no option is selected. */
  placeholder?: string;
  /** Fallback text when there are no options. */
  emptyText?: string;
  /** Label rendered above the select. */
  label?: ReactNode;
  /** Helper text rendered below the select. Hidden when `error` is set. */
  description?: ReactNode;
  /** Error message; marks the select invalid. */
  error?: ReactNode;
  /** Marks the field as required and renders an asterisk. */
  required?: boolean;
  /** Content rendered at the start of the select. */
  prefix?: ReactNode;
  /** Content rendered at the end of the select. Replaces the default chevron. */
  suffix?: ReactNode;
};

export const Select = forwardRef<HTMLSelectElement, SelectProps>(
  (
    {
      className,
      id,
      style,
      size = "sm",
      variant = "subtle",
      options = [],
      value,
      defaultValue,
      onValueChange,
      placeholder = "Select option",
      emptyText = "No options",
      label,
      description,
      error,
      required,
      disabled,
      prefix,
      suffix,
      onChange,
      "aria-describedby": ariaDescribedBy,
      ...props
    },
    ref,
  ) => {
    const generatedId = useId();
    const selectId = id ?? generatedId;
    const descriptionId = `${selectId}-description`;
    const errorId = `${selectId}-error`;
    const hasError = Boolean(error);
    const hasLabeling = Boolean(label || description || error);
    const isControlled = value !== undefined;
    const [internalValue, setInternalValue] = useState(defaultValue ?? null);
    const currentValue = isControlled ? value : internalValue;
    const suffixRef = useRef<HTMLSpanElement | null>(null);
    const [suffixWidth, setSuffixWidth] = useState(0);

    useEffect(() => {
      const element = suffixRef.current;
      if (!element) return;
      const measure = () => setSuffixWidth(element.offsetWidth);
      measure();
      const observer = new ResizeObserver(measure);
      observer.observe(element);
      return () => observer.disconnect();
    }, []);

    const normalizedOptions = options
      .map((option) => (typeof option === "string" ? { label: option, value: option } : option))
      .filter((option) => option.value !== undefined && option.value !== null);

    const selectedIndex = normalizedOptions.findIndex((option) => option.value === currentValue);
    const encodedValue = selectedIndex >= 0 ? String(selectedIndex) : "";
    const hasValue = selectedIndex >= 0;
    const describedBy =
      [
        description && !hasError ? descriptionId : null,
        hasError ? errorId : null,
        ariaDescribedBy,
      ]
        .filter(Boolean)
        .join(" ") || undefined;
    const padding = prefix ? paddingClasses[size].withPrefix : paddingClasses[size].plain;

    return (
      <div className={cn(hasLabeling && "flex flex-col gap-1.5", hasLabeling && className)}>
        {label ? (
          <label
            htmlFor={selectId}
            className="block [font-size:var(--label-font-size,13px)] [font-weight:var(--label-font-weight,420)] leading-tighter [color:var(--label-color,var(--ink-gray-6))]"
          >
            {label}
            {required ? requiredMark : null}
          </label>
        ) : null}
        <div className={cn("relative flex items-center", !hasLabeling && className)}>
          {prefix ? (
            <span
              className={cn(
                "pointer-events-none absolute inset-y-0 start-0 flex items-center",
                prefixPadding[size],
                disabled ? "text-ink-gray-5" : "text-ink-gray-8",
              )}
            >
              {prefix}
            </span>
          ) : null}
          <select
            ref={ref}
            id={selectId}
            value={encodedValue}
            required={required}
            disabled={disabled}
            aria-required={required || undefined}
            aria-invalid={hasError || undefined}
            aria-errormessage={hasError ? errorId : undefined}
            aria-describedby={describedBy}
            data-slot="control"
            data-size={size}
            data-variant={variant}
            data-state={hasError ? "invalid" : "valid"}
            data-placeholder={!hasValue ? "" : undefined}
            data-disabled={disabled ? "true" : undefined}
            data-required={required ? "true" : undefined}
            style={{
              ...style,
              paddingInlineEnd: suffixWidth ? suffixWidth + 8 : undefined,
            }}
            className={cn(
              "w-full cursor-pointer appearance-none border leading-tighter transition-colors outline-none data-[state=invalid]:border-outline-red-6 data-[state=invalid]:focus:border-outline-red-7 disabled:cursor-not-allowed disabled:border-surface-gray-2 disabled:bg-surface-gray-1 disabled:text-ink-gray-5",
              sizeClasses[size],
              padding,
              variantClasses[variant],
              hasValue ? "text-ink-gray-8" : "text-ink-gray-6",
            )}
            onChange={(event) => {
              const index = Number(event.currentTarget.value);
              const next =
                event.currentTarget.value === "" || Number.isNaN(index)
                  ? null
                  : (normalizedOptions[index]?.value ?? null);
              if (!isControlled) setInternalValue(next);
              onValueChange?.(next);
              onChange?.(event);
            }}
            {...props}
          >
            <option value="" disabled={required}>
              {normalizedOptions.length === 0 ? emptyText : placeholder}
            </option>
            {normalizedOptions.map((option, index) => (
              <option key={`${option.value}-${index}`} value={String(index)} disabled={option.disabled}>
                {option.label}
              </option>
            ))}
          </select>
          <span
            ref={suffixRef}
            className={cn(
              "pointer-events-none absolute inset-y-0 end-0 flex items-center",
              suffixPadding[size],
              disabled ? "text-ink-gray-5" : "text-ink-gray-7",
            )}
          >
            {suffix ?? (
              <ChevronDown aria-hidden="true" className={chevronSizeClasses[size]} />
            )}
          </span>
        </div>
        {description && !hasError ? (
          <p
            id={descriptionId}
            className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-gray-5"
          >
            {description}
          </p>
        ) : null}
        {hasError ? (
          <p
            id={errorId}
            role="alert"
            className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-red-7"
          >
            {error}
          </p>
        ) : null}
      </div>
    );
  },
);

Select.displayName = "Select";

/* TextInput component tokens — mirrors frappe-ui v1 control geometry. */
:root {
  /* Size: xs (24px) */
  --input-xs-height: 24px;
  --input-xs-radius: var(--radius-3);
  --input-xs-font-size: 12px;

  /* Size: sm (28px) */
  --input-sm-height: 28px;
  --input-sm-radius: var(--radius-4);
  --input-sm-font-size: 14px;

  /* Size: md (32px) */
  --input-md-height: 32px;
  --input-md-radius: var(--radius-4);
  --input-md-font-size: 14px;

  /* Size: lg (40px) */
  --input-lg-height: 40px;
  --input-lg-radius: var(--radius-5);
  --input-lg-font-size: 16px;

  --input-description-font-size: 13px;
}

import type { ComponentPropsWithoutRef } from "react";
import { cn } from "@/lib/utils";

export type SkeletonProps = ComponentPropsWithoutRef<"div">;

export function Skeleton({ className, ...props }: SkeletonProps) {
  return (
    <div
      aria-hidden="true"
      className={cn("espresso-skeleton animate-pulse bg-surface-gray-3", className)}
      {...props}
    />
  );
}

/* Skeleton uses Tailwind's pulse animation; this hook keeps it calm when
   the person prefers reduced motion. */
@media (prefers-reduced-motion: reduce) {
  .espresso-skeleton {
    animation-duration: 2s;
  }
}

import { useId, useRef } from "react";
import type { HTMLAttributes, ReactNode } from "react";
import { Slider as ArkSlider } from "@ark-ui/react/slider";
import { cn } from "@/lib/utils";
import { ErrorMessage } from "./ErrorMessage";
import { Label } from "./Label";

export type SliderSize = "sm" | "md";
export type SliderValue = number[];
export type SliderError =
  | string
  | string[]
  | (Error & { messages?: string | string[] })
  | null;

export type SliderProps = Omit<HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> & {
  /** Current value as an array. One number for a single handle, two for a range. */
  value?: SliderValue;
  /** Initial value for uncontrolled use. */
  defaultValue?: SliderValue;
  /** Called on every step of a drag. */
  onValueChange?: (value: SliderValue) => void;
  /** Called once when a drag ends. */
  onValueCommit?: (value: SliderValue) => void;
  /** Lowest value. Defaults to 0. */
  min?: number;
  /** Highest value. Defaults to 100. */
  max?: number;
  /** Step between values. Defaults to 1. */
  step?: number;
  /** Visual size of the track and handle. */
  size?: SliderSize;
  /** Disables the slider. */
  disabled?: boolean;
  /** Label rendered above the track. */
  label?: ReactNode;
  /** Helper text rendered below the track. Hidden when `error` is set. */
  description?: ReactNode;
  /** Error message, lines, or an Error. */
  error?: SliderError;
  /** Marks the field as required. */
  required?: boolean;
};

const sizeClasses = {
  sm: {
    control: "h-4",
    track: "h-1",
    thumb: "size-4",
  },
  md: {
    control: "h-5",
    track: "h-1.5",
    thumb: "size-5",
  },
};

function errorPresent(error: SliderError | undefined) {
  if (!error) return false;
  if (Array.isArray(error)) return error.filter(Boolean).length > 0;
  if (error instanceof Error) return Boolean(error.message);
  return Boolean(error);
}

export function Slider({
  value,
  defaultValue,
  onValueChange,
  onValueCommit,
  min = 0,
  max = 100,
  step = 1,
  size = "sm",
  disabled = false,
  label,
  description,
  error,
  required = false,
  className,
  children,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: SliderProps) {
  const baseId = useId().replace(/:/g, "");
  const labelId = `${baseId}-label`;
  const descriptionId = `${baseId}-description`;
  const errorId = `${baseId}-error`;
  const rootRef = useRef<HTMLDivElement>(null);
  const hasError = errorPresent(error);
  const hasLabeling = Boolean(label || description || hasError);
  const values = value ?? defaultValue ?? [min];
  const thumbCount = Math.max(1, values.length);
  const isRange = thumbCount > 1;
  const labelText = typeof label === "string" ? label : "";
  const parts = isRange
    ? thumbCount === 2
      ? ["minimum", "maximum"]
      : Array.from({ length: thumbCount }, (_, index) => `value ${index + 1} of ${thumbCount}`)
    : [];

  const thumbNameIds = Array.from({ length: thumbCount }, (_, index) => `${baseId}-name-${index}`);
  const thumbNames = parts.map((part) => {
    const text = labelText ? `${labelText} ${part}` : part;
    return text.charAt(0).toUpperCase() + text.slice(1);
  });

  const defaultAriaLabel = isRange
    ? thumbNames
    : labelText
      ? [labelText]
      : ["Value"];

  const resolvedAriaLabelledBy =
    ariaLabelledBy ?? (isRange ? thumbNameIds : labelText ? [labelId] : undefined);
  const resolvedAriaLabel = ariaLabel ?? (resolvedAriaLabelledBy ? undefined : defaultAriaLabel);

  const describedBy =
    [
      description && !hasError ? descriptionId : null,
      hasError ? errorId : null,
    ]
      .filter(Boolean)
      .join(" ") || undefined;

  const thumbClasses = cn(
    "block rounded-full bg-surface-base shadow-md ring-1 ring-outline-gray-3 transition-shadow duration-150 ease-out hover:ring-4 hover:ring-outline-gray-3/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ink-gray-8 focus-visible:ring-offset-2 focus-visible:ring-offset-surface-base",
    sizeClasses[size].thumb,
    disabled ? "cursor-not-allowed" : "cursor-grab active:cursor-grabbing",
  );

  return (
    <div className={cn(hasLabeling && "flex flex-col gap-1.5", hasLabeling && className)}>
      {label ? (
        <Label
          id={labelId}
          required={required}
          onClick={() => {
            rootRef.current?.querySelector<HTMLElement>('[role="slider"]')?.focus();
          }}
        >
          {label}
        </Label>
      ) : null}
      <div ref={rootRef} className={cn(!hasLabeling && className)}>
        {isRange
          ? thumbNames.map((name, index) => (
              <span key={thumbNameIds[index]} id={thumbNameIds[index]} className="sr-only">
                {name}
              </span>
            ))
          : null}
        <ArkSlider.Root
          value={value}
          defaultValue={value === undefined ? (defaultValue ?? [min]) : undefined}
          onValueChange={(details) => onValueChange?.(details.value)}
          onValueChangeEnd={(details) => onValueCommit?.(details.value)}
          min={min}
          max={max}
          step={step}
          disabled={disabled}
          invalid={hasError}
          origin={min < 0 && max > 0 ? "center" : "start"}
          aria-label={resolvedAriaLabel as string[] | undefined}
          aria-labelledby={resolvedAriaLabelledBy as string[] | undefined}
          ids={{ thumb: (index) => `${baseId}-thumb-${index}` }}
          data-slot="slider"
          data-size={size}
          data-state={hasError ? "invalid" : "valid"}
          className="w-full"
          {...props}
        >
          <ArkSlider.Control
            data-slot="control"
            className={cn(
              "relative flex w-full touch-none select-none items-center",
              sizeClasses[size].control,
            )}
          >
            <ArkSlider.Track
              data-slot="track"
              className={cn(
                "relative w-full grow rounded-4",
                sizeClasses[size].track,
                disabled ? "bg-surface-gray-2" : "bg-surface-gray-3",
              )}
            >
              <ArkSlider.Range
                data-slot="range"
                className={cn(
                  "absolute h-full rounded-4",
                  disabled ? "bg-surface-gray-4" : "bg-surface-gray-10",
                )}
              />
            </ArkSlider.Track>
            {Array.from({ length: thumbCount }, (_, index) => (
              <ArkSlider.Thumb
                key={index}
                index={index}
                data-slot="thumb"
                aria-describedby={describedBy}
                aria-invalid={hasError || undefined}
                aria-errormessage={hasError ? errorId : undefined}
                className={thumbClasses}
              >
                <ArkSlider.HiddenInput />
              </ArkSlider.Thumb>
            ))}
          </ArkSlider.Control>
        </ArkSlider.Root>
      </div>
      {description && !hasError ? (
        <p
          id={descriptionId}
          className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-gray-5"
        >
          {description}
        </p>
      ) : null}
      {hasError ? <ErrorMessage id={errorId} message={error} /> : null}
      {children}
    </div>
  );
}

/* The handle is positioned by Ark UI; only the drag affordance is ours. */
[data-slot="thumb"] {
  touch-action: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="thumb"] {
    transition: none;
  }
}

import { forwardRef } from "react";
import type { ComponentPropsWithoutRef } from "react";
import { cn } from "@/lib/utils";

const sizeMap = {
  xs: { px: 12, thickness: 1.5, inset: 0.9 },
  sm: { px: 14, thickness: 2, inset: 1.05 },
  md: { px: 16, thickness: 2, inset: 1.2 },
  lg: { px: 20, thickness: 2, inset: 1.5 },
};

const colorClasses = {
  gray: "text-ink-gray-8",
  red: "text-ink-red-7",
};

type SpinnerSize = keyof typeof sizeMap;
type SpinnerTheme = keyof typeof colorClasses;

export type SpinnerProps = Omit<ComponentPropsWithoutRef<"svg">, "color"> & {
  /** Diameter: xs 12px, sm 14px, md 16px, lg 20px. */
  size?: SpinnerSize;
  /** Fixed color. Omit to inherit the current text color. */
  theme?: SpinnerTheme;
  /** Draws a faint full-circle track behind the arc. */
  track?: boolean;
};

export const Spinner = forwardRef<SVGSVGElement, SpinnerProps>(
  ({ className, size, theme, track = false, style, ...props }, ref) => {
    const dimensions = size ? sizeMap[size] : undefined;
    const spinnerStyle = dimensions
      ? {
          width: `${dimensions.px}px`,
          height: `${dimensions.px}px`,
          "--spinner-thickness": `${dimensions.thickness}px`,
          "--spinner-mask-thickness": `${dimensions.thickness}px`,
          "--spinner-inset": `${dimensions.inset}px`,
        }
      : {};
    const rootStyle = { ...spinnerStyle, ...style };

    return (
      <svg
        ref={ref}
        width="16"
        height="16"
        role="status"
        aria-label="Loading"
        className={cn(
          "espresso-spinner inline-block shrink-0",
          theme && colorClasses[theme],
          track && "espresso-spinner--track",
          className,
        )}
        style={rootStyle}
        {...props}
      />
    );
  },
);

Spinner.displayName = "Spinner";

/* Spinner paints a rotating conic-gradient comet inside a masked ring.
   The gradient angle is registered so it can interpolate smoothly. */
@property --spinner-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.espresso-spinner {
  --spinner-thickness: 14.7%;
  --spinner-mask-thickness: 29.4%;
  --spinner-inset: 7.5%;
  --spinner-paint-size: calc(100% - 2 * var(--spinner-inset));
  --spinner-track-color: transparent;
  background-image:
    radial-gradient(
      calc(var(--spinner-thickness) / 2) calc(var(--spinner-thickness) / 2) at
        calc(50% + (50% - var(--spinner-thickness) / 2) * sin(var(--spinner-angle)))
        calc(50% - (50% - var(--spinner-thickness) / 2) * cos(var(--spinner-angle))),
      currentColor 92%,
      transparent
    ),
    conic-gradient(from var(--spinner-angle), transparent 32%, currentColor 92%, currentColor 100%),
    linear-gradient(var(--spinner-track-color), var(--spinner-track-color));
  background-size: var(--spinner-paint-size) var(--spinner-paint-size);
  background-position: center;
  background-repeat: no-repeat;
  -webkit-mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - 0.5px),
      transparent 100%
    )
    center / var(--spinner-paint-size) var(--spinner-paint-size) no-repeat;
  mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - 0.5px),
      transparent 100%
    )
    center / var(--spinner-paint-size) var(--spinner-paint-size) no-repeat;
  animation: espresso-spinner-rotate 0.7s linear infinite;
}

.espresso-spinner--track {
  --spinner-track-color: color-mix(in srgb, currentColor 15%, transparent);
}

@keyframes espresso-spinner-rotate {
  to {
    --spinner-angle: 360deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .espresso-spinner {
    animation-duration: 1.6s;
  }
}

import { forwardRef, useId, useState } from "react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

const trackSizeClasses = {
  xs: "h-(--switch-xs-height) w-(--switch-xs-width) border-2",
  sm: "h-(--switch-sm-height) w-(--switch-sm-width) border-2",
  md: "h-(--switch-md-height) w-(--switch-md-width) border-[3px]",
};

const thumbSizeClasses = {
  xs: "size-(--switch-xs-thumb-size)",
  sm: "size-(--switch-sm-thumb-size)",
  md: "size-(--switch-md-thumb-size)",
};

const thumbTravelClasses = {
  xs: "translate-x-(--switch-xs-travel)",
  sm: "translate-x-(--switch-sm-travel)",
  md: "translate-x-(--switch-md-travel)",
};

const paddedSizeClasses = {
  xs: "h-(--switch-xs-height) px-1.5",
  sm: "h-(--switch-sm-height) px-1.5",
  md: "h-(--switch-md-height) px-3",
};

const gapClasses = {
  xs: "gap-x-2.5",
  sm: "gap-x-2.5",
  md: "gap-x-3.5",
};

const errorIndentClasses = {
  xs: "ps-8",
  sm: "ps-9",
  md: "ps-[42px]",
};

const requiredMark = (
  <>
    <span className="select-none [color:var(--label-required-color,var(--ink-red-5))]" aria-hidden="true">
      *
    </span>
    <span className="sr-only">(required)</span>
  </>
);

type SwitchSize = keyof typeof trackSizeClasses;

export type SwitchProps = Omit<ComponentPropsWithoutRef<"button">, "onChange" | "type"> & {
  /** Controls the size of the switch. */
  size?: SwitchSize;
  /** Checked state. */
  checked?: boolean;
  /** Initial checked state for uncontrolled use. */
  defaultChecked?: boolean;
  /** Called when the checked state changes. */
  onCheckedChange?: (checked: boolean) => void;
  /** Label rendered beside the switch. */
  label?: ReactNode;
  /** Helper text rendered below the switch. Hidden when `error` is set. */
  description?: ReactNode;
  /** Error message; marks the switch invalid. */
  error?: ReactNode;
  /** Marks the field as required and renders an asterisk. */
  required?: boolean;
  /** Wraps the control and label in a clickable surface. */
  padded?: boolean;
  /** Places the control before or after the label. */
  controlPosition?: "start" | "end";
  /** Optional icon rendered before the label. */
  icon?: ReactNode;
};

export const Switch = forwardRef<HTMLButtonElement, SwitchProps>(
  (
    {
      className,
      id,
      size = "sm",
      checked,
      defaultChecked = false,
      onCheckedChange,
      label,
      description,
      error,
      required,
      disabled,
      padded = false,
      controlPosition = "end",
      icon,
      onClick,
      "aria-describedby": ariaDescribedBy,
      ...props
    },
    ref,
  ) => {
    const generatedId = useId();
    const inputId = id ?? generatedId;
    const descriptionId = `${inputId}-description`;
    const errorId = `${inputId}-error`;
    const hasError = Boolean(error);
    const hasLabel = Boolean(label);
    const hasDetail = Boolean(description || error);
    const isControlled = checked !== undefined;
    const [internalChecked, setInternalChecked] = useState(defaultChecked);
    const isChecked = isControlled ? Boolean(checked) : internalChecked;
    const describedBy =
      [
        description && !hasError ? descriptionId : null,
        hasError ? errorId : null,
        ariaDescribedBy,
      ]
        .filter(Boolean)
        .join(" ") || undefined;

    const toggle = () => {
      if (disabled) return;
      const next = !isChecked;
      if (!isControlled) setInternalChecked(next);
      onCheckedChange?.(next);
    };

    const control = (
      <button
        ref={ref}
        id={inputId}
        type="button"
        role="switch"
        aria-checked={isChecked}
        aria-required={required || undefined}
        aria-invalid={hasError || undefined}
        aria-errormessage={hasError ? errorId : undefined}
        aria-describedby={describedBy}
        disabled={disabled}
        data-slot="control"
        data-size={size}
        data-state={isChecked ? "checked" : "unchecked"}
        data-disabled={disabled ? "true" : undefined}
        data-required={required ? "true" : undefined}
        className={cn(
          "relative inline-flex shrink-0 cursor-pointer items-center rounded-full border-2 transition-colors duration-100 ease-in-out aria-invalid:ring-1 aria-invalid:ring-outline-red-6 focus-visible:ring-2 focus-visible:ring-ink-gray-8 focus-visible:ring-offset-2 focus-visible:ring-offset-surface-base",
          trackSizeClasses[size],
          disabled
            ? "cursor-not-allowed border-outline-gray-3 bg-surface-gray-3"
            : isChecked
              ? "border-transparent bg-surface-gray-10 enabled:hover:bg-surface-gray-9 active:bg-surface-gray-8"
              : "border-outline-gray-4 bg-surface-gray-5 enabled:hover:border-outline-gray-5 enabled:hover:bg-surface-gray-6 active:bg-surface-gray-7",
        )}
        onClick={(event) => {
          onClick?.(event);
          if (!event.defaultPrevented) toggle();
        }}
        {...props}
      >
        <span
          aria-hidden="true"
          className={cn(
            "pointer-events-none inline-block transform rounded-full bg-surface-base shadow ring-0 transition duration-100 ease-in-out",
            thumbSizeClasses[size],
            isChecked ? thumbTravelClasses[size] : "translate-x-0",
          )}
        />
      </button>
    );

    return (
      <div
        className={cn(
          "flex flex-col",
          padded && "group rounded-(--switch-padded-radius) transition-colors",
          padded &&
            !disabled &&
            "cursor-pointer hover:bg-surface-gray-3 active:bg-surface-gray-4 [&:has(:focus-visible)]:ring-2 [&:has(:focus-visible)]:ring-ink-gray-8 [&:has(:focus-visible)]:ring-offset-2 [&:has(:focus-visible)]:ring-offset-surface-base [&_button:focus-visible]:ring-0 [&_button:focus-visible]:ring-offset-0",
          padded && disabled && "cursor-not-allowed",
          padded &&
            (hasDetail
              ? size === "md"
                ? "px-3 py-2"
                : size === "sm"
                  ? "px-2 py-1.5"
                  : "px-1.5 py-1.5"
              : paddedSizeClasses[size]),
          padded && (controlPosition === "start" ? "w-fit" : "w-full"),
          className,
        )}
        onClick={(event) => {
          if (disabled) return;
          const target = event.target as HTMLElement;
          if (target.closest('button[role="switch"]') || target.closest("label")) return;
          toggle();
        }}
      >
        <div
          className={cn(
            "flex items-center",
            controlPosition === "start" ? "flex-row-reverse justify-end" : "justify-between",
            gapClasses[size],
            !padded && "py-1.5",
          )}
        >
          <div className="flex min-w-0 flex-col gap-1">
            <div className="flex items-center">
              {icon ? (
                <span className="me-2 inline-flex size-4 shrink-0 items-center justify-center text-ink-gray-6" aria-hidden="true">
                  {icon}
                </span>
              ) : null}
              {hasLabel ? (
                <label
                  htmlFor={inputId}
                  className={cn(
                    "select-none leading-tight [font-size:var(--label-font-size,13px)] [font-weight:var(--label-font-weight,420)] [color:var(--label-color,var(--ink-gray-6))]",
                    disabled
                      ? "cursor-not-allowed [color:var(--label-disabled-color,var(--ink-gray-4))]"
                      : "cursor-pointer",
                  )}
                >
                  {label}
                  {required ? requiredMark : null}
                </label>
              ) : null}
            </div>
          </div>
          {control}
        </div>
        {hasDetail ? (
          <div
            className={cn(
              "mt-1",
              controlPosition === "start" ? errorIndentClasses[size] : undefined,
              !hasLabel && "ps-0",
            )}
          >
            {description && !hasError ? (
              <p
                id={descriptionId}
                className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-gray-5"
              >
                {description}
              </p>
            ) : null}
            {hasError ? (
              <p
                id={errorId}
                role="alert"
                className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-red-7"
              >
                {error}
              </p>
            ) : null}
          </div>
        ) : null}
      </div>
    );
  },
);

Switch.displayName = "Switch";

/* Switch component tokens — mirrors frappe-ui v1 toggle geometry. */
:root {
  --switch-radius: var(--radius-full);
  --switch-padded-radius: var(--radius-4);

  --switch-xs-height: 14px;
  --switch-xs-width: 24px;
  --switch-xs-thumb-size: 10px;
  --switch-xs-travel: 10px;

  --switch-sm-height: 16px;
  --switch-sm-width: 26px;
  --switch-sm-thumb-size: 12px;
  --switch-sm-travel: 10px;

  --switch-md-height: 20px;
  --switch-md-width: 32px;
  --switch-md-thumb-size: 14px;
  --switch-md-travel: 12px;

  --input-description-font-size: 13px;
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import type { HTMLAttributes, KeyboardEvent, MouseEvent, ReactNode } from "react";
import { cn } from "@/lib/utils";

export type TabButtonValue = string | number;
export type TabButtonsVariant = "subtle" | "ghost" | "underline" | "browser-tab";
export type TabButtonsSize = "sm" | "md";

export type TabButtonOption = {
  /** Value this option picks. */
  value: TabButtonValue;
  /** Visible label. Becomes the accessible name for an icon-only option. */
  label: string;
  /** Icon-only option. The label is rendered for screen readers only. */
  icon?: ReactNode;
  /** Leading accent icon shown next to a visible label. */
  iconLeft?: ReactNode;
  /** Disables this option. */
  disabled?: boolean;
  /** Renders the option as a link. */
  href?: string;
  /** Called when the option is clicked. */
  onClick?: (event: MouseEvent<HTMLElement>) => void;
};

export type TabButtonsProps = Omit<
  HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> & {
  /** Options to render. */
  options?: TabButtonOption[];
  /** Selected value. Omit for uncontrolled use. */
  value?: TabButtonValue;
  /** Initially selected value for uncontrolled use. */
  defaultValue?: TabButtonValue;
  /** Called when the selected value changes. */
  onValueChange?: (value: TabButtonValue) => void;
  /** Visual treatment, shared with the Tabs family. */
  variant?: TabButtonsVariant;
  /** Height and padding of the options. */
  size?: TabButtonsSize;
  /** Stack the options vertically. */
  vertical?: boolean;
  /** Options share the container width equally. */
  fluid?: boolean;
};

const trackClasses = {
  subtle: "bg-surface-gray-2 gap-1 p-px",
  ghost: "bg-surface-base gap-1 p-px",
  underline: "gap-6 border-b border-outline-gray-1",
  "browser-tab": "gap-1 border-b border-outline-gray-1",
};

const trackRadiusClasses = {
  subtle: "rounded-4",
  ghost: "rounded-4",
  underline: "",
  "browser-tab": "",
};

const indicatorSurfaceClasses = {
  subtle: "bg-surface-elevation-3 shadow-base rounded-[7px]",
  ghost: "bg-surface-gray-2 rounded-[7px]",
  underline: "bg-outline-gray-8",
  "browser-tab": "",
};

function pillSizeClasses(
  variant: TabButtonsVariant,
  size: TabButtonsSize,
  vertical: boolean,
  iconOnly: boolean,
) {
  if (iconOnly) return size === "sm" ? "size-6.5 p-[5px]" : "size-7 p-[5px]";

  if (variant === "underline") {
    if (vertical) return size === "sm" ? "h-6.5 gap-2 px-2" : "h-7 gap-2 px-2";
    return size === "sm" ? "h-7 gap-2" : "h-8 gap-2";
  }

  if (variant === "browser-tab") {
    if (vertical) return size === "sm" ? "h-6.5 gap-2 px-2" : "h-7 gap-2 px-2.5";
    return size === "sm" ? "h-7 gap-2 px-2 py-[5px]" : "h-8 gap-2 px-2.5 py-[7px]";
  }

  return size === "sm" ? "h-6.5 gap-2 px-2 py-[5px]" : "h-7 gap-2 px-2.5 py-1.5";
}

function pillRadiusClasses(
  variant: TabButtonsVariant,
  size: TabButtonsSize,
) {
  if (variant === "underline") return "";
  if (variant === "subtle") return size === "sm" ? "rounded-[7px]" : "rounded-[9px]";
  if (variant === "browser-tab") return "rounded-t-4";
  return size === "sm" ? "rounded-[7px]" : "rounded-4";
}

export function TabButtons({
  options = [],
  value,
  defaultValue,
  onValueChange,
  variant = "subtle",
  size = "sm",
  vertical = false,
  fluid = false,
  className,
  onKeyDown,
  ...props
}: TabButtonsProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const selected = value !== undefined ? value : internalValue;
  const trackRef = useRef<HTMLDivElement>(null);
  const [indicator, setIndicator] = useState<{ x: number; y: number; width: number; height: number } | null>(null);
  const [animated, setAnimated] = useState(false);
  const isPill = variant === "subtle" || variant === "ghost";

  const measure = useCallback(() => {
    const track = trackRef.current;
    if (!track) {
      setIndicator(null);
      return;
    }
    const active = track.querySelector<HTMLElement>('[data-slot="tab-button"][data-state="active"]');
    if (!active) {
      setIndicator(null);
      return;
    }

    const trackRect = track.getBoundingClientRect();
    const rect = active.getBoundingClientRect();
    const style = getComputedStyle(track);
    const border = {
      top: parseFloat(style.borderTopWidth) || 0,
      bottom: parseFloat(style.borderBottomWidth) || 0,
      left: parseFloat(style.borderLeftWidth) || 0,
      right: parseFloat(style.borderRightWidth) || 0,
    };
    const x = rect.left - trackRect.left - border.left;
    const y = rect.top - trackRect.top - border.top;

    if (variant === "underline") {
      if (vertical) {
        const innerWidth = trackRect.width - border.left - border.right;
        setIndicator({ x: innerWidth, y, width: 1, height: rect.height });
      } else {
        const innerHeight = trackRect.height - border.top - border.bottom;
        setIndicator({ x, y: innerHeight, width: rect.width, height: 1 });
      }
      return;
    }

    setIndicator({ x, y, width: rect.width, height: rect.height });
  }, [variant, vertical]);

  useLayoutEffect(() => {
    measure();
  }, [measure, selected, options, size]);

  useEffect(() => {
    const track = trackRef.current;
    if (!track || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => measure());
    observer.observe(track);
    return () => observer.disconnect();
  }, [measure]);

  useEffect(() => {
    const frame = requestAnimationFrame(() => requestAnimationFrame(() => setAnimated(true)));
    return () => cancelAnimationFrame(frame);
  }, []);

  function select(next: TabButtonValue) {
    if (value === undefined) setInternalValue(next);
    onValueChange?.(next);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;

    const enabled = options.filter((option) => !option.disabled);
    if (!enabled.length) return;
    const currentIndex = enabled.findIndex((option) => option.value === selected);
    const forwardKey = vertical ? "ArrowDown" : "ArrowRight";
    const backwardKey = vertical ? "ArrowUp" : "ArrowLeft";
    let nextIndex = currentIndex;

    if (event.key === "Home") nextIndex = 0;
    else if (event.key === "End") nextIndex = enabled.length - 1;
    else if (event.key === forwardKey || event.key === backwardKey) {
      const step = event.key === forwardKey ? 1 : -1;
      nextIndex = (Math.max(currentIndex, 0) + step + enabled.length) % enabled.length;
    } else {
      return;
    }

    event.preventDefault();
    const next = enabled[nextIndex];
    select(next.value);
    requestAnimationFrame(() => {
      trackRef.current
        ?.querySelector<HTMLElement>(`[data-slot="tab-button"][data-value="${String(next.value)}"]`)
        ?.focus();
    });
  }

  const activeIndex = options.findIndex((option) => option.value === selected);

  return (
    <div
      ref={trackRef}
      role="radiogroup"
      aria-orientation={vertical ? "vertical" : "horizontal"}
      data-slot="tab-buttons"
      data-variant={variant}
      data-size={size}
      data-orientation={vertical ? "vertical" : "horizontal"}
      className={cn(
        "flex",
        fluid ? "w-full" : "inline-flex shrink-0",
        vertical ? "flex-col" : "items-center",
        isPill && "relative isolate",
        variant === "underline" && "relative",
        trackClasses[variant],
        trackRadiusClasses[variant],
        className,
      )}
      onKeyDown={handleKeyDown}
      {...props}
    >
      {isPill ? (
        <div
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute inset-0 overflow-hidden",
            trackRadiusClasses[variant],
          )}
        >
          <div
            data-slot="tab-indicator"
            className={cn(
              "absolute left-0 top-0 -z-10 motion-reduce:transition-none",
              animated && "transition-[width,height,transform] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)]",
              indicatorSurfaceClasses[variant],
            )}
            style={
              indicator
                ? {
                    width: indicator.width,
                    height: indicator.height,
                    transform: `translate(${indicator.x}px, ${indicator.y}px)`,
                  }
                : { display: "none" }
            }
          />
        </div>
      ) : null}
      {variant === "underline" ? (
        <div
          aria-hidden="true"
          data-slot="tab-indicator"
          className={cn(
            "absolute left-0 top-0 bg-outline-gray-8 motion-reduce:transition-none",
            animated && "transition-[width,height,transform] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)]",
          )}
          style={
            indicator
              ? {
                  width: indicator.width,
                  height: indicator.height,
                  transform: `translate(${indicator.x}px, ${indicator.y}px)`,
                }
              : { display: "none" }
          }
        />
      ) : null}
      {options.map((option) => {
        const isActive = option.value === selected;
        const iconOnly = Boolean(option.icon) && !option.iconLeft;
        const tabbable = option.disabled
          ? -1
          : isActive
            ? 0
            : activeIndex === -1 && options.filter((item) => !item.disabled)[0]?.value === option.value
              ? 0
              : -1;

        const content = (
          <span
            className={cn(
              "inline-flex box-border shrink-0 select-none items-center justify-center whitespace-nowrap outline-none transition-[background-color,color,box-shadow] duration-150 ease-out motion-reduce:transition-none",
              variant === "subtle" ? "text-sm leading-[16.1px]" : "text-base leading-tighter",
              isActive ? "text-ink-gray-8" : "text-ink-gray-5",
              size === "md" && variant !== "underline" && variant !== "subtle"
                ? "font-medium tracking-[0.015em]"
                : "",
              pillSizeClasses(variant, size, vertical, iconOnly),
              pillRadiusClasses(variant, size),
              !isActive && "hover:text-ink-gray-8",
            )}
          >
            {option.icon ? (
              <span
                className={cn(
                  "inline-flex shrink-0 items-center justify-center [&_svg]:size-full",
                  size === "sm" ? "size-4" : "size-4.5",
                )}
              >
                {option.icon}
              </span>
            ) : null}
            {option.iconLeft ? (
              <span
                className={cn(
                  "inline-flex shrink-0 items-center justify-center [&_svg]:size-full",
                  size === "sm" ? "size-4" : "size-4.5",
                )}
              >
                {option.iconLeft}
              </span>
            ) : null}
            <span className={cn(iconOnly ? "sr-only" : "min-w-0 truncate")}>{option.label}</span>
          </span>
        );

        const shared = {
          role: "radio" as const,
          "aria-checked": isActive,
          "aria-label": iconOnly ? option.label : undefined,
          tabIndex: tabbable,
          "data-slot": "tab-button",
          "data-state": isActive ? ("active" as const) : ("inactive" as const),
          "data-value": String(option.value),
          className: cn(
            "inline-flex appearance-none p-0 text-inherit no-underline focus-visible:ring-0",
            variant === "browser-tab"
              ? isActive
                ? "relative -mb-px rounded-t-4 border border-outline-gray-1 border-b-transparent bg-surface-base"
                : "border border-transparent"
              : "border-0 bg-transparent",
            vertical && "w-full",
            fluid && "flex-1 min-w-0",
            option.disabled && "pointer-events-none opacity-60",
          ),
          onClick: (event: MouseEvent<HTMLElement>) => {
            option.onClick?.(event);
            if (!event.defaultPrevented && !option.disabled) select(option.value);
          },
        };

        if (option.href) {
          return (
            <a key={String(option.value)} href={option.href} target="_blank" rel="noreferrer noopener" {...shared}>
              {content}
            </a>
          );
        }

        return (
          <button key={String(option.value)} type="button" disabled={option.disabled} {...shared}>
            {content}
          </button>
        );
      })}
    </div>
  );
}

/* The active surface slides between options; the track keeps the motion short. */
[data-slot="tab-indicator"] {
  will-change: transform, width, height;
}

[data-slot="tab-button"] {
  -webkit-tap-highlight-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="tab-indicator"] {
    transition: none;
  }
}

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";

export type TabValue = string | number;
export type TabsVariant = "underline" | "subtle" | "ghost" | "browser-tab";
export type TabsSize = "sm" | "md";
export type TabsOrientation = "horizontal" | "vertical";

type TabsContextValue = {
  value: TabValue | undefined;
  select: (value: TabValue) => void;
  orientation: TabsOrientation;
  variant: TabsVariant;
  size: TabsSize;
  baseId: string;
};

type TabListContextValue = {
  variant: TabsVariant;
  size: TabsSize;
  orientation: TabsOrientation;
};

export type TabsProps = Omit<HTMLAttributes<HTMLDivElement>, "defaultValue" | "onChange"> & {
  /** Selected tab value. Omit for uncontrolled use. */
  value?: TabValue;
  /** Initially selected tab for uncontrolled use. */
  defaultValue?: TabValue;
  /** Called when the selected tab changes. */
  onValueChange?: (value: TabValue) => void;
  /** Visual treatment of the trigger row. */
  variant?: TabsVariant;
  /** Height and padding of the triggers. */
  size?: TabsSize;
  /** Render the list vertically instead of horizontally. */
  vertical?: boolean;
  /** Explicit orientation; wins over `vertical`. */
  orientation?: TabsOrientation;
};

export type TabListProps = HTMLAttributes<HTMLDivElement> & {
  variant?: TabsVariant;
  size?: TabsSize;
};

export type TabTriggerProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value"> & {
  /** Value this trigger selects. */
  value: TabValue;
  /** Visible label. Children take precedence. */
  label?: ReactNode;
  /** Leading icon before the label. */
  icon?: ReactNode;
  /** Content before the icon and label. */
  prefix?: ReactNode;
  /** Content after the label, such as a count. */
  suffix?: ReactNode;
};

export type TabPanelProps = HTMLAttributes<HTMLDivElement> & {
  /** Value of the trigger that owns this panel. */
  value: TabValue;
  /** Keep the panel mounted while hidden. */
  keepMounted?: boolean;
};

const TabsContext = createContext<TabsContextValue | null>(null);
const TabListContext = createContext<TabListContextValue | null>(null);

function useTabsContext() {
  const context = useContext(TabsContext);
  if (!context) throw new Error("Tabs parts must be used inside <Tabs>.");
  return context;
}

function useTabListContext() {
  const context = useContext(TabListContext);
  if (!context) throw new Error("<TabTrigger> must be used inside <TabList>.");
  return context;
}

function slug(value: TabValue) {
  return String(value).replace(/[^a-zA-Z0-9_-]/g, "-");
}

function tabId(baseId: string, value: TabValue) {
  return `${baseId}-tab-${slug(value)}`;
}

function panelId(baseId: string, value: TabValue) {
  return `${baseId}-panel-${slug(value)}`;
}

const sizeClasses = {
  sm: "h-8 px-2.5 text-sm",
  md: "h-9 px-3 text-sm",
};

const triggerVariantClasses = {
  underline: {
    base: "text-ink-gray-5 hover:text-ink-gray-7",
    selected:
      "text-ink-gray-8 after:absolute after:inset-x-0 after:-bottom-px after:h-px after:bg-outline-gray-8",
    verticalSelected:
      "text-ink-gray-8 after:absolute after:inset-y-0 after:-right-px after:w-px after:bg-outline-gray-8",
  },
  subtle: {
    base: "rounded-(--radius-3) text-ink-gray-5 hover:text-ink-gray-7",
    selected: "rounded-(--radius-3) bg-surface-base text-ink-gray-8 shadow-sm",
    verticalSelected: "rounded-(--radius-3) bg-surface-base text-ink-gray-8 shadow-sm",
  },
  ghost: {
    base: "rounded-(--radius-3) text-ink-gray-5 hover:text-ink-gray-7",
    selected: "rounded-(--radius-3) bg-surface-gray-3 text-ink-gray-8",
    verticalSelected: "rounded-(--radius-3) bg-surface-gray-3 text-ink-gray-8",
  },
  "browser-tab": {
    base: "rounded-t-(--radius-4) text-ink-gray-5 hover:text-ink-gray-7",
    selected:
      "-mb-px rounded-t-(--radius-4) border border-outline-gray-2 border-b-surface-base bg-surface-base text-ink-gray-8",
    verticalSelected:
      "-mr-px rounded-l-(--radius-4) border border-outline-gray-2 border-r-surface-base bg-surface-base text-ink-gray-8",
  },
};

const listVariantClasses = {
  underline: {
    horizontal: "relative flex items-center border-b border-outline-gray-2",
    vertical: "relative flex flex-col border-r border-outline-gray-2",
  },
  subtle: {
    horizontal: "inline-flex items-center gap-1 rounded-(--radius-4) bg-surface-gray-2 p-1",
    vertical: "inline-flex flex-col items-stretch gap-1 rounded-(--radius-4) bg-surface-gray-2 p-1",
  },
  ghost: {
    horizontal: "inline-flex items-center gap-1 rounded-(--radius-4) p-1",
    vertical: "inline-flex flex-col items-stretch gap-1 rounded-(--radius-4) p-1",
  },
  "browser-tab": {
    horizontal: "relative flex items-end gap-1 border-b border-outline-gray-2",
    vertical: "relative flex flex-col gap-1 border-r border-outline-gray-2",
  },
};

export function Tabs({
  value,
  defaultValue,
  onValueChange,
  variant = "underline",
  size = "sm",
  vertical = false,
  orientation,
  className,
  children,
  ...props
}: TabsProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const selected = value !== undefined ? value : internalValue;
  const resolvedOrientation = orientation ?? (vertical ? "vertical" : "horizontal");
  const baseId = useId().replace(/:/g, "");

  function select(next: TabValue) {
    if (value === undefined) setInternalValue(next);
    onValueChange?.(next);
  }

  return (
    <TabsContext.Provider
      value={{ value: selected, select, orientation: resolvedOrientation, variant, size, baseId }}
    >
      <div
        data-slot="tabs"
        data-orientation={resolvedOrientation}
        data-variant={variant}
        data-size={size}
        className={cn("min-w-0", className)}
        {...props}
      >
        {children}
      </div>
    </TabsContext.Provider>
  );
}

export function TabList({ variant, size, className, children, onKeyDown, ...props }: TabListProps) {
  const context = useTabsContext();
  const rootRef = useRef<HTMLDivElement>(null);
  const listVariant = variant ?? context.variant;
  const listSize = size ?? context.size;
  const isVertical = context.orientation === "vertical";

  useEffect(() => {
    if (context.value !== undefined) return;
    const first = rootRef.current?.querySelector<HTMLButtonElement>('[role="tab"]:not(:disabled)');
    first?.click();
  }, [context.value]);

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;

    const tabs = Array.from(
      rootRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]:not(:disabled)') ?? [],
    );
    if (!tabs.length) return;

    const currentIndex = tabs.indexOf(document.activeElement as HTMLButtonElement);
    const nextKey = isVertical ? ["ArrowDown", "ArrowUp"] : ["ArrowRight", "ArrowLeft"];
    let nextIndex = currentIndex;

    if (event.key === "Home") nextIndex = 0;
    else if (event.key === "End") nextIndex = tabs.length - 1;
    else if (event.key === nextKey[0] || event.key === nextKey[1]) {
      const direction = event.key === nextKey[0] ? 1 : -1;
      nextIndex = (Math.max(currentIndex, 0) + direction + tabs.length) % tabs.length;
    } else {
      return;
    }

    event.preventDefault();
    const next = tabs[nextIndex];
    next.focus();
    next.click();
  }

  return (
    <TabListContext.Provider
      value={{ variant: listVariant, size: listSize, orientation: context.orientation }}
    >
      <div
        ref={rootRef}
        role="tablist"
        aria-orientation={context.orientation}
        data-slot="tab-list"
        data-variant={listVariant}
        data-size={listSize}
        className={cn(
          listVariantClasses[listVariant][context.orientation],
          isVertical && "self-start",
          className,
        )}
        onKeyDown={handleKeyDown}
        {...props}
      >
        {children}
      </div>
    </TabListContext.Provider>
  );
}

export function TabTrigger({
  value,
  label,
  icon,
  prefix,
  suffix,
  disabled = false,
  className,
  children,
  onClick,
  ...props
}: TabTriggerProps) {
  const context = useTabsContext();
  const list = useTabListContext();
  const selected = context.value === value;
  const isVertical = list.orientation === "vertical";
  const variantClasses = triggerVariantClasses[list.variant];

  return (
    <button
      type="button"
      role="tab"
      id={tabId(context.baseId, value)}
      aria-selected={selected}
      aria-controls={panelId(context.baseId, value)}
      tabIndex={disabled ? -1 : selected ? 0 : -1}
      disabled={disabled}
      data-slot="tab-trigger"
      data-state={selected ? "active" : "inactive"}
      className={cn(
        "relative inline-flex items-center justify-center gap-1.5 whitespace-nowrap font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-outline-gray-4 disabled:cursor-not-allowed disabled:opacity-50",
        sizeClasses[list.size],
        variantClasses.base,
        selected && (isVertical && variantClasses.verticalSelected
          ? variantClasses.verticalSelected
          : variantClasses.selected),
        list.variant === "browser-tab" && "px-3",
        isVertical && "w-full justify-start",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) context.select(value);
      }}
      {...props}
    >
      {prefix}
      {icon}
      {children ?? label}
      {suffix}
    </button>
  );
}

export function TabPanel({ value, keepMounted = false, className, children, ...props }: TabPanelProps) {
  const context = useTabsContext();
  const selected = context.value === value;

  if (!selected && !keepMounted) return null;

  return (
    <div
      role="tabpanel"
      id={panelId(context.baseId, value)}
      aria-labelledby={tabId(context.baseId, value)}
      tabIndex={0}
      hidden={!selected}
      data-slot="tab-panel"
      className={cn("outline-none", className)}
      {...props}
    >
      {children}
    </div>
  );
}

/* Tabs use color transitions only; the moving indicator is intentionally omitted. */
[data-slot="tab-trigger"] {
  -webkit-tap-highlight-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="tab-trigger"] {
    transition: none;
  }
}

import { forwardRef, useEffect, useId, useRef, useState } from "react";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

const sizeClasses = {
  xs: "h-(--input-xs-height) rounded-(--input-xs-radius) [font-size:var(--input-xs-font-size)]",
  sm: "h-(--input-sm-height) rounded-(--input-sm-radius) [font-size:var(--input-sm-font-size)]",
  md: "h-(--input-md-height) rounded-(--input-md-radius) [font-size:var(--input-md-font-size)]",
  lg: "h-(--input-lg-height) rounded-(--input-lg-radius) [font-size:var(--input-lg-font-size)]",
};

const paddingClasses = {
  xs: { plain: "px-1.5", withPrefix: "ps-7", withSuffix: "ps-1.5", both: "ps-7" },
  sm: { plain: "px-2", withPrefix: "ps-8", withSuffix: "ps-2", both: "ps-8" },
  md: { plain: "px-2.5", withPrefix: "ps-9", withSuffix: "ps-2.5", both: "ps-9" },
  lg: { plain: "px-3", withPrefix: "ps-10", withSuffix: "ps-3", both: "ps-10" },
};

const prefixPadding = {
  xs: "ps-1.5",
  sm: "ps-2",
  md: "ps-2.5",
  lg: "ps-3",
};

const suffixPadding = {
  xs: "pe-1.5",
  sm: "pe-2",
  md: "pe-2.5",
  lg: "pe-3",
};

const variantClasses = {
  subtle:
    "border-surface-gray-2 bg-surface-gray-2 hover:border-outline-elevation-2 hover:bg-surface-gray-3 focus:border-outline-gray-4 focus:bg-surface-base focus:shadow-sm",
  outline:
    "border-outline-gray-2 bg-surface-base hover:border-outline-gray-3 hover:shadow-sm focus:border-outline-gray-4 focus:bg-surface-base focus:shadow-sm",
  ghost:
    "border-transparent bg-transparent focus-visible:ring-2 focus-visible:ring-ink-gray-8 focus-visible:ring-offset-2 focus-visible:ring-offset-surface-base",
};

const requiredMark = (
  <>
    <span className="select-none [color:var(--label-required-color,var(--ink-red-5))]" aria-hidden="true">
      *
    </span>
    <span className="sr-only">(required)</span>
  </>
);

type TextInputSize = keyof typeof sizeClasses;
type TextInputVariant = keyof typeof variantClasses;

export type TextInputProps = Omit<ComponentPropsWithoutRef<"input">, "size" | "prefix"> & {
  /** Visual size of the input. */
  size?: TextInputSize;
  /** Surface treatment of the input. */
  variant?: TextInputVariant;
  /** Label rendered above the input. */
  label?: ReactNode;
  /** Helper text rendered below the input. Hidden when `error` is set. */
  description?: ReactNode;
  /** Error message; marks the input invalid. */
  error?: ReactNode;
  /** Marks the field as required and renders an asterisk. */
  required?: boolean;
  /** Content rendered at the start of the input. */
  prefix?: ReactNode;
  /** Content rendered at the end of the input. */
  suffix?: ReactNode;
};

export const TextInput = forwardRef<HTMLInputElement, TextInputProps>(
  (
    {
      className,
      id,
      style,
      size = "sm",
      variant = "subtle",
      label,
      description,
      error,
      required,
      disabled,
      prefix,
      suffix,
      "aria-describedby": ariaDescribedBy,
      ...props
    },
    ref,
  ) => {
    const generatedId = useId();
    const inputId = id ?? generatedId;
    const descriptionId = `${inputId}-description`;
    const errorId = `${inputId}-error`;
    const hasError = Boolean(error);
    const hasLabeling = Boolean(label || description || error);
    const suffixRef = useRef<HTMLSpanElement | null>(null);
    const [suffixWidth, setSuffixWidth] = useState(0);

    useEffect(() => {
      const element = suffixRef.current;
      if (!element) return;
      const measure = () => setSuffixWidth(element.offsetWidth);
      measure();
      const observer = new ResizeObserver(measure);
      observer.observe(element);
      return () => observer.disconnect();
    }, [suffix]);
    const describedBy =
      [
        description && !hasError ? descriptionId : null,
        hasError ? errorId : null,
        ariaDescribedBy,
      ]
        .filter(Boolean)
        .join(" ") || undefined;

    const padding = prefix && suffix
      ? paddingClasses[size].both
      : prefix
        ? paddingClasses[size].withPrefix
        : suffix
          ? paddingClasses[size].withSuffix
          : paddingClasses[size].plain;

    return (
      <div className={cn(hasLabeling && "flex flex-col gap-1.5", hasLabeling && className)}>
        {label ? (
          <label
            htmlFor={inputId}
            className="block [font-size:var(--label-font-size,13px)] [font-weight:var(--label-font-weight,420)] leading-tighter [color:var(--label-color,var(--ink-gray-6))]"
          >
            {label}
            {required ? requiredMark : null}
          </label>
        ) : null}
        <div className={cn("relative flex items-center", !hasLabeling && className)}>
          {prefix ? (
            <span
              className={cn(
                "pointer-events-none absolute inset-y-0 start-0 flex items-center",
                prefixPadding[size],
                disabled ? "text-ink-gray-5" : "text-ink-gray-8",
              )}
            >
              {prefix}
            </span>
          ) : null}
          <input
            ref={ref}
            id={inputId}
            required={required}
            disabled={disabled}
            aria-required={required || undefined}
            aria-invalid={hasError || undefined}
            aria-errormessage={hasError ? errorId : undefined}
            aria-describedby={describedBy}
            data-slot="control"
            data-size={size}
            data-variant={variant}
            data-state={hasError ? "invalid" : "valid"}
            data-disabled={disabled ? "true" : undefined}
            data-required={required ? "true" : undefined}
            style={{
              ...style,
              paddingInlineEnd: suffixWidth ? suffixWidth + 8 : undefined,
            }}
            className={cn(
              "w-full border leading-tighter text-ink-gray-8 transition-colors outline-none placeholder:text-ink-gray-6 data-[state=invalid]:border-outline-red-6 data-[state=invalid]:focus:border-outline-red-7 disabled:cursor-not-allowed disabled:border-surface-gray-2 disabled:bg-surface-gray-1 disabled:text-ink-gray-5 disabled:placeholder:text-ink-gray-4",
              sizeClasses[size],
              padding,
              variantClasses[variant],
            )}
            {...props}
          />
          {suffix ? (
            <span
              ref={suffixRef}
              className={cn(
                "pointer-events-none absolute inset-y-0 end-0 flex items-center",
                suffixPadding[size],
                disabled ? "text-ink-gray-5" : "text-ink-gray-8",
              )}
            >
              {suffix}
            </span>
          ) : null}
        </div>
        {description && !hasError ? (
          <p
            id={descriptionId}
            className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-gray-5"
          >
            {description}
          </p>
        ) : null}
        {hasError ? (
          <p
            id={errorId}
            role="alert"
            className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-red-7"
          >
            {error}
          </p>
        ) : null}
      </div>
    );
  },
);

TextInput.displayName = "TextInput";

/* TextInput component tokens — mirrors frappe-ui v1 control geometry. */
:root {
  /* Size: xs (24px) */
  --input-xs-height: 24px;
  --input-xs-radius: var(--radius-3);
  --input-xs-font-size: 12px;

  /* Size: sm (28px) */
  --input-sm-height: 28px;
  --input-sm-radius: var(--radius-4);
  --input-sm-font-size: 14px;

  /* Size: md (32px) */
  --input-md-height: 32px;
  --input-md-radius: var(--radius-4);
  --input-md-font-size: 14px;

  /* Size: lg (40px) */
  --input-lg-height: 40px;
  --input-lg-radius: var(--radius-5);
  --input-lg-font-size: 16px;

  --input-description-font-size: 13px;
}

