    const errorId = `${inputId}-error`;
    const hasError = Boolean(error);
    const hasLabeling = Boolean(label || description || error);
    const describedBy =
      [
        description && !hasError ? descriptionId : null,
        hasError ? errorId : null,
        ariaDescribedBy,
      ]
        .filter(Boolean)
        .join(" ") || undefined;

    return (
      <div className={cn(hasLabeling && "flex flex-col gap-1.5", hasLabeling && className)}>
        {label ? (
          <label
            htmlFor={inputId}
            className="block [font-size:var(--label-font-size,13px)] [font-weight:var(--label-font-weight,420)] leading-tighter [color:var(--label-color,var(--ink-gray-6))]"
          >
            {label}
            {required ? requiredMark : null}
          </label>
        ) : null}
        <textarea
          ref={ref}
          id={inputId}
          rows={rows}
          required={required}
          disabled={disabled}
          aria-required={required || undefined}
          aria-invalid={hasError || undefined}
          aria-errormessage={hasError ? errorId : undefined}
          aria-describedby={describedBy}
          data-slot="control"
          data-size={size}
          data-variant={variant}
          data-state={hasError ? "invalid" : "valid"}
          data-disabled={disabled ? "true" : undefined}
          data-required={required ? "true" : undefined}
          className={cn(
            "block w-full resize-y border [font-size:var(--textarea-font-size)] leading-tighter text-ink-gray-8 transition-colors outline-none placeholder:text-ink-gray-6 data-[state=invalid]:border-outline-red-6 data-[state=invalid]:focus:border-outline-red-7 disabled:cursor-not-allowed disabled:border-surface-gray-2 disabled:bg-surface-gray-1 disabled:text-ink-gray-5 disabled:placeholder:text-ink-gray-4",
            sizeClasses[size],
            variantClasses[variant],
            !hasLabeling && className,
          )}
          {...props}
        />
        {description && !hasError ? (
          <p
            id={descriptionId}
            className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-gray-5"
          >
            {description}
          </p>
        ) : null}
        {hasError ? (
          <p
            id={errorId}
            role="alert"
            className="[font-size:var(--input-description-font-size)] leading-tighter text-ink-red-7"
          >
            {error}
          </p>
        ) : null}
      </div>
    );
  },
);

Textarea.displayName = "Textarea";

/* Textarea component tokens — mirrors frappe-ui v1 textarea geometry. */
:root {
  --input-xs-radius: var(--radius-3);
  --input-sm-radius: var(--radius-4);
  --input-md-radius: var(--radius-4);
  --input-lg-radius: var(--radius-5);

  --textarea-xs-min-height: 32px;
  --textarea-sm-min-height: 36px;
  --textarea-md-min-height: 40px;
  --textarea-lg-min-height: 44px;
  --textarea-font-size: 13px;

  --input-description-font-size: 13px;
}

import type { ReactNode } from "react";
import { Tooltip as ArkTooltip } from "@ark-ui/react/tooltip";
import { Portal } from "@ark-ui/react/portal";

export type TooltipSide = "top" | "right" | "bottom" | "left";

export type TooltipProps = {
  /** The trigger. It should be one focusable element. */
  children: ReactNode;
  /** Text shown inside the tooltip when `content` is not provided. */
  text?: string;
  /** Rich content that replaces `text` inside the bubble. */
  content?: ReactNode;
  /** Delay before opening on hover, in milliseconds. */
  hoverDelay?: number;
  /** Side of the trigger to open on. */
  side?: TooltipSide;
  /** Gap between the trigger and the bubble, in pixels. */
  offset?: number;
  /** Render content without the dark bubble shell. */
  bare?: boolean;
  /** Disable the tooltip while keeping the trigger. */
  disabled?: boolean;
};

export function Tooltip({
  children,
  text = "",
  content,
  hoverDelay = 500,
  side = "top",
  offset = 4,
  bare = false,
  disabled = false,
}: TooltipProps) {
  if (disabled) return <>{children}</>;

  return (
    <ArkTooltip.Root
      openDelay={hoverDelay}
      closeDelay={75}
      positioning={{ placement: side, gutter: offset }}
    >
      <ArkTooltip.Trigger asChild data-slot="trigger">
        {children}
      </ArkTooltip.Trigger>
      {text || content ? (
        <Portal>
          <ArkTooltip.Positioner className="[--z-index:100]!">
            <ArkTooltip.Content data-slot="tooltip-content" className="z-[100] [--z-index:100]!">
              {bare ? (
                content
              ) : (
                <div
                  data-slot="bubble"
                  className="rounded-(--radius-4) bg-surface-gray-10 px-2 py-1 text-xs text-ink-base shadow-xl"
                >
                  {content ?? text}
                </div>
              )}
              <ArkTooltip.Arrow data-slot="tooltip-arrow">
                <ArkTooltip.ArrowTip data-slot="tooltip-arrow-tip" />
              </ArkTooltip.Arrow>
            </ArkTooltip.Content>
          </ArkTooltip.Positioner>
        </Portal>
      ) : null}
    </ArkTooltip.Root>
  );
}

/* Tooltip enters from its trigger with a short, origin-aware scale. */
[data-slot="tooltip-content"] {
  transform-origin: var(--transform-origin);
  transition:
    opacity 125ms ease-out,
    transform 125ms ease-out;
}

[data-slot="tooltip-content"][data-state="closed"] {
  opacity: 0;
  transform: scale(0.97);
}

[data-slot="tooltip-arrow"] {
  --arrow-size: 8px;
  --arrow-background: var(--surface-gray-10);
}

[data-slot="tooltip-arrow-tip"] {
  width: var(--arrow-size);
  height: var(--arrow-size);
  border-radius: 2px;
  background: var(--arrow-background);
  transform: rotate(45deg);
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="tooltip-content"] {
    transition: opacity 125ms ease;
  }

  [data-slot="tooltip-content"][data-state="closed"] {
    transform: none;
  }
}
